function injectBreadcrumb(key){if(key==='overview'||content.querySelector('.page-breadcrumb,.todo-breadcrumb,.limited-breadcrumb,.plan-create-breadcrumb,.case-create-breadcrumb'))return;const parts=breadcrumbMap[key]||[title.textContent||'当前页面'];content.insertAdjacentHTML('afterbegin',`<div class="page-breadcrumb">${parts.slice(0,-1).join('　/　')}${parts.length>1?'　/　':''}<span>${parts.at(-1)}</span></div>`)}
function jobListStatus(j){if(j.listStatus)return j.listStatus;if(j.status==='待审批')return '申请中';if(j.status==='执行中')return '作业中';if(j.status==='已完成')return '已完成';return j.status}
function jobProgress(j){return jobListStatus(j)==='已完成'?'验收完成':j.risk==='一般风险'?'气体检测':'风险评估'}
function workTypeMatches(type,configured){const clean=x=>String(x||'').replace(/作业|受限/g,'').replace('有限空间','有限空间');return clean(type)===clean(configured)}
function configureJobGroupPage(){const group=workTypeHierarchy.find(x=>x.name===activeWorkGroup)||{name:activeWorkGroup,children:[]},children=group.children||[],launcher=document.querySelector('.job-launcher');const breadcrumb=document.querySelector('.page-breadcrumb');if(breadcrumb)breadcrumb.innerHTML=`作业管理　/　<span>${group.name}</span>`;if(launcher){launcher.querySelector('h2').textContent=`发起${group.name}`;launcher.querySelector('p').textContent=children.length?'先选择作业类型，再创建对应的作业票':'当前未维护二级作业类型，可直接发起该类作业';const create=launcher.querySelector('#newJob');create.textContent='＋ 新增作业';selectedJobType=children[0]||group.name;const switcher=launcher.querySelector('.work-template-switch');if(children.length){switcher.style.display='';switcher.querySelector('.work-type-tags').innerHTML=children.map((x,i)=>`<button class="${i===0?'active':''}"><span>${x}</span></button>`).join('')}else switcher.style.display='none'}const typeFilter=document.querySelector('#typeFilter');if(typeFilter)typeFilter.innerHTML=`<option>全部作业类型</option>${children.map(x=>`<option>${x}</option>`).join('')}`}
function jobActions(j){const status=jobListStatus(j),base=[['复制新增','copy'],['作业详情','detail'],['删除','delete','danger']];if(status==='申请中')return [...base,['终止作业','terminate','danger'],['智能检测','smart'],['实时/回放监控','monitor','disabled']];if(status==='作业中'||status==='已完成')return [...base,['作业票','ticket'],['智能检测','smart'],['监护记录','guard'],['实时/回放监控','monitor']];if(status==='作废')return [['复制新增','copy'],['作业详情','detail'],['重新申请','copy'],['删除','delete','danger']];return base}
function jobRow(j,i){const status=jobListStatus(j),statusClass=status==='申请中'?'pending':status==='作业中'?'running':status==='已完成'?'done':'void';return `<tr><td>${i+1}</td><td><button class="job-link" data-action="detail" data-id="${j.id}">${j.id}</button></td><td>${j.type}</td><td>${j.level||['测试','一级','三级','特级','二级'][i%5]}</td><td><b>${j.name}</b><small>${j.content||j.name}</small></td><td><b>${j.owner}</b><small>${j.workUnit||'鞍钢集团矿业有限公司'}</small></td><td><span class="time-mark start">起</span> ${j.start||j.time.split(' — ')[0]}<br><span class="time-mark end">末</span> ${j.end||j.time.split(' — ')[1]||j.time}</td><td>${j.area.split(' · ').pop()}</td><td><span class="progress-tag">${jobProgress(j)}</span></td><td>${j.applyTime||'2026-08-31 16:16'}</td><td>${status==='已完成'?'-':j.owner}</td><td><span class="status ${statusClass}">${status}</span></td><td><div class="job-ops compact"><button class="job-op primary-op" data-action="detail" data-id="${j.id}">查看详情</button><button class="job-op more-op" data-action="more" data-id="${j.id}" aria-label="更多操作">•••</button></div></td></tr>`}
function jobStatusTabs(empty=false){const counts=empty?[0,0,0,0,0]:[13,7,2,2,2];return `<button class="${current==='全部'?'active':''}" data-status="全部">全部状态 <span>${counts[0]}</span></button><button class="${current==='申请中'?'active':''}" data-status="申请中">申请中 <span>${counts[1]}</span></button><button class="${current==='作业中'?'active':''}" data-status="作业中">作业中 <span>${counts[2]}</span></button><button class="${current==='已完成'?'active':''}" data-status="已完成">已完成 <span>${counts[3]}</span></button><button class="${current==='作废'?'active':''}" data-status="作废">已作废 <span>${counts[4]}</span></button>`}
function setupJobs(){const rows=document.querySelector('#jobRows');if(!rows)return;const statusTabs=document.querySelector('.job-status-tabs');if(statusTabs)statusTabs.innerHTML=jobStatusTabs();const group=workTypeHierarchy.find(x=>x.name===activeWorkGroup)||{children:[]},allowed=group.children||[],list=[...jobs,{name:'Test_测试动火作业3',id:'DH20251215002',type:'动火作业',risk:'较大风险',area:'鞍钢集团矿业有限公司 · 东鞍山烧结厂',time:'2025-12-16 09:49 — 17:49',owner:'安全生产鞍钢项目',status:'作废',listStatus:'作废',color:'#22c3df',level:'一级',content:'Test_测试动火作业3'},{name:'测试动火作业3',id:'DH20251203003',type:'动火作业',risk:'较大风险',area:'鞍钢集团矿业有限公司 · 东鞍山烧结厂',time:'2025-12-04 15:00 — 23:00',owner:'安全生产鞍钢项目',status:'作废',listStatus:'作废',color:'#22c3df',level:'一级',content:'测试动火作业3'}];const renderChips=()=>{const box=document.querySelector('#activeFilters');if(!box)return;const scopeLabel={applied:'我申请的',joined:'我参与的',all:'全部作业'}[currentScope];box.innerHTML=`<span>当前条件</span><button data-clear="scope">${scopeLabel} ×</button><button data-clear="status">${current==='全部'?'全部状态':current} ×</button>`};const render=()=>{hideJobMoreActions(true);const q=document.querySelector('#search').value.trim(),type=document.querySelector('#typeFilter').value,unit=document.querySelector('#unitFilter').value;document.querySelectorAll('.job-status-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.status===current));document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.scope===currentScope));const data=list.filter((j,i)=>allowed.some(x=>workTypeMatches(j.type,x))&&(current==='全部'||jobListStatus(j)===current)&&(type==='全部作业类型'||workTypeMatches(j.type,type))&&(unit==='全部所属单位'||j.area.includes(unit))&&(currentScope==='all'||currentScope==='applied'&&i!==2||currentScope==='joined'&&i<4)&&(!q||`${j.name}${j.id}${j.owner}${j.workUnit||''}`.includes(q)));rows.innerHTML=data.map(jobRow).join('')||`<tr><td colspan="13" class="empty"><b>暂无${activeWorkGroup}作业记录</b><small>${allowed.length?'请尝试调整筛选条件':'请先在参数配置中维护二级作业类型，或点击上方按钮发起作业'}</small></td></tr>`;renderChips()};document.querySelectorAll('.job-status-tabs button').forEach(b=>b.onclick=()=>{current=b.dataset.status;render()});document.querySelectorAll('.tabs button[data-scope]').forEach(b=>b.onclick=()=>{currentScope=b.dataset.scope;render()});document.querySelector('#search').oninput=render;document.querySelector('#typeFilter').onchange=render;document.querySelector('#unitFilter').onchange=render;document.querySelector('#reset').onclick=()=>{document.querySelector('#search').value='';document.querySelector('#typeFilter').selectedIndex=0;document.querySelector('#unitFilter').selectedIndex=0;current='全部';currentScope='applied';render()};document.querySelector('#activeFilters').onclick=e=>{const b=e.target.closest('[data-clear]');if(!b)return;if(b.dataset.clear==='status')current='全部';if(b.dataset.clear==='scope')currentScope='all';render()};rows.onclick=e=>{const b=e.target.closest('[data-action]');if(!b)return;const j=list.find(x=>x.id===b.dataset.id);if(b.dataset.action==='more')return showJobMoreActions(j,render,b);hideJobMoreActions(true);handleJobAction(b.dataset.action,j,render)};rows.onmouseover=e=>{const b=e.target.closest('.more-op');if(!b||b.contains(e.relatedTarget))return;const j=list.find(x=>x.id===b.dataset.id);showJobMoreActions(j,render,b)};rows.onmouseout=e=>{const b=e.target.closest('.more-op');if(!b||b.contains(e.relatedTarget))return;scheduleJobMoreHide()};document.querySelector('#newJob').onclick=()=>{toast(`正在创建${selectedJobType}`);showNewJob()};document.querySelector('.more-filter').onclick=()=>toast('可继续增加作业等级、负责人和申请日期筛选');setupWorkTypeTags();render()}
