const finishStandards=[['动火作业','1.现场无遗留火种，易燃物品未覆盖在动火点上。 2.在施工期间及完工后60分钟内进行防火巡视。 3.现场电气设施电源已切断，现场整理整顿到位。'],['高处作业','1.现场无遗留的零件、工具等。 2.人员已经全部离开登高作业平台。 3.现场整理整顿，器材归位。'],['吊装作业','1.现场吊物已摆放稳妥。 2.吊具、吊钩等均已收置稳妥。 3.现场警戒区和警戒标志拆除。'],['受限空间作业','1.现场无遗留的零件、工具等。 2.现场整理整顿，器材归位。 3.作业人员全部撤出有限空间。'],['临时用电作业','1.临时配电箱、漏电保护等已拆除。 2.现场整理整顿，器材归位。'],['断路作业','1.现场交通警示设施等已拆除。 2.报告有关单位恢复通行。'],['动土作业','1.临时警戒线等已拆除。 2.现场整理整顿，无残留渣土。 3.挖方基坑已经填平。'],['盲板抽堵作业','1.现场临时警戒线等已拆除。 2.现场恢复原貌。'],['常规作业','1.现场无遗留的零件、工具等。 2.现场整理整顿，器材归位。']];
const configTabs=['综合配置','作业类型配置','风险内容配置','安全交底配置','结束确认标准'];
function configView(){return `<div class="config-layout">${orgTree()}<section class="panel config-main"><div class="config-tabs">${configTabs.map((x,i)=>`<button class="${i===0?'active':''}" data-config="${i}">${x}</button>`).join('')}</div><div id="configBody">${configBody(0)}</div></section></div>`}
function configBody(i){if(i===0)return generalConfigView();if(i===1)return jobLevelConfigView();if(i===2)return riskConfigView();if(i===3)return briefingConfigView();if(i===4)return finishStandardView();return ''}
function configTable(head,rows){return `<div class="table-wrap"><table class="config-table"><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}<th>操作</th></tr></thead><tbody>${rows.map((r,i)=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}<td><button class="detail">编辑</button>　<button class="danger-text">删除</button></td></tr>`).join('')}</tbody></table></div>`}
function workTypeSettingRows(){return workTypeHierarchy.map((group,gi)=>`<tbody class="work-type-group"><tr class="work-type-parent" data-group="${gi}"><td><button class="tree-toggle">⌄</button> ${gi+1}</td><td><b>${group.name}</b><small>一级节点</small></td><td><span class="status done">启用</span></td><td><button class="detail add-work-child">添加子级</button><button class="detail edit-work-type">编辑</button><button class="danger-text delete-work-type">删除</button></td></tr>${group.children.map((name,ci)=>`<tr class="work-type-child" data-group="${gi}" data-child="${ci}"><td>${gi+1}.${ci+1}</td><td>└ ${name}<small>二级节点</small></td><td><span class="status done">启用</span></td><td><button class="detail edit-work-type">编辑</button><button class="danger-text delete-work-type">删除</button></td></tr>`).join('')}</tbody>`).join('')}
function generalConfigView(){const settings=[['作业编号规则','按作业类型+日期+流水号自动生成',true],['是否需要初审','作业票进入风险评估前需完成初审',false],['是否必须风险评估','所有作业票必须完成风险辨识和管控措施确认',true],['是否必须安全交底','作业人员接收交底并签字后方可开工',true],['是否允许“不涉及”','安全措施可标记为不涉及并填写原因',true],['是否必须签名','审批、交底、验收节点必须完成电子签名',true],['是否必须上传附件','关键节点必须上传现场或方案附件',false],['超时、归档和版本规则','配置审批超时提醒、作业票归档周期及模板版本规则',true]];return `<div class="general-config"><section class="general-module work-type-setting"><div class="module-title"><div><b>▶ 作业类型设置</b><span>维护一级作业类型和二级作业类型</span></div><button class="primary" id="addWorkTypeGroup">＋ 新增一级节点</button></div><div class="table-wrap"><table><thead><tr><th>排序</th><th>作业类型名称</th><th>状态</th><th>操作</th></tr></thead>${workTypeSettingRows()}</table></div></section><section class="general-module"><div class="module-title"><div><b>▶ 全局业务规则</b><span>适用于所有作业计划、一件一案和作业类型</span></div></div>${settings.map(x=>`<div class="setting"><b>${x[0]}</b><label><button data-toggle="on" class="${x[2]?'active':''}">开启</button><button data-toggle="off" class="${x[2]?'':'active'}">关闭</button></label><p>${x[1]}</p></div>`).join('')}</section><section class="general-module gas-config"><div class="module-title"><div><b>▶ 检测气体</b><span>维护气体名称、单位和合格标准</span></div><button class="primary" id="addGas">新增气体</button></div><div class="table-wrap"><table><thead><tr><th>序号</th><th>气体名称</th><th>气体单位</th><th>合格标准</th><th>操作</th></tr></thead><tbody id="gasRows">${gasRows()}</tbody></table></div></section></div>`}
function gasRows(){return gasConfigs.map((x,i)=>`<tr data-index="${i}"><td>${i+1}</td><td>${x.name}</td><td>${x.unit}</td><td>${x.operator} ${x.standard}</td><td><button class="detail gas-edit">编辑</button><button class="danger-text gas-delete">删除</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">暂无检测气体</td></tr>'}
function jobLevelConfigView(){return `<div class="config-toolbar level-toolbar"><span></span><div><button class="primary" id="addJobLevel">＋ 新增作业等级</button><button class="primary" id="sortJobLevel">⇅ 排序</button></div></div><div class="table-wrap"><table class="job-level-table"><thead><tr><th>作业类型</th><th>作业等级</th><th>定义</th><th>必须上传作业方案</th><th>作业票最长有效期</th><th>操作</th><th>作业票最长有效期</th><th>作业审批节点</th><th>验收审批节点</th><th>操作</th></tr></thead><tbody id="jobLevelRows">${jobLevelRows()}</tbody></table></div>`}
function jobLevelRows(){return [...new Set(jobLevelConfigs.map(x=>x[0]))].map(type=>{const group=jobLevelConfigs.map((x,i)=>({x,i})).filter(v=>v.x[0]===type);return group.map(({x,i},row)=>`<tr data-index="${i}">${row===0?`<td rowspan="${group.length}" class="merged-work-type"><b>${type}</b><small>${group.length} 个等级</small></td>`:''}<td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td><td><button class="detail level-edit">编辑</button><button class="danger-text level-delete">删除</button></td></tr>`).join('')}).join('')}
function briefingConfigView(){return `<div class="config-scope-bar"><label>作业类型<select><option>全部作业类型</option><option>动火作业</option><option>有限空间作业</option></select></label><label>作业等级<select><option>全部等级</option><option>一级</option><option>二级</option></select></label><label>业务模式<select><option>全部模式</option><option>普通作业</option><option>作业计划</option><option>一件一案</option></select></label><label>交底版本<input value="V1.0"></label></div><div class="briefing-head"><div><b>安全交底预设配置</b><span>维护作业步骤、安全防范措施、禁入区域、交底确认语和签名要求</span></div><button class="primary" id="addBriefing">＋新增</button></div><div class="table-wrap"><table><thead><tr><th>序号</th><th>内容</th><th>适用范围</th><th>签名要求</th><th>操作</th></tr></thead><tbody id="briefingRows">${briefingConfigs.map((x,i)=>`<tr><td>${i+1}</td><td>${x}</td><td>有限空间作业 / 一级 / 一件一案</td><td>必须签名</td><td><button class="detail briefing-edit">编辑</button><button class="danger-text briefing-delete">删除</button></td></tr>`).join('')}</tbody></table></div>`}
function briefingRows(){return briefingConfigs.map((x,i)=>`<tr data-index="${i}"><td>${i+1}</td><td>${x}</td><td><button class="detail briefing-edit">编辑</button><button class="danger-text briefing-delete">删除</button></td></tr>`).join('')||'<tr><td colspan="3" class="empty">暂无安全交底内容</td></tr>'}
function finishStandardView(){return `<div class="config-scope-bar"><label>作业类型<select><option>全部作业类型</option><option>动火作业</option><option>高处作业</option></select></label><label>作业等级<select><option>全部等级</option><option>一级</option><option>二级</option></select></label><label>业务模式<select><option>全部模式</option><option>普通作业</option><option>作业计划</option><option>一件一案</option></select></label></div><div class="finish-standard"><h3>结束确认标准</h3><div class="table-wrap"><table><thead><tr><th>序号</th><th>作业类型</th><th>作业等级</th><th>业务模式</th><th>内容</th><th>操作</th></tr></thead><tbody>${finishStandards.map((x,i)=>`<tr data-index="${i}"><td>${i+1}</td><td>${x[0]}</td><td>一级</td><td>作业计划</td><td>${x[1]}</td><td><button class="detail finish-edit">编辑</button></td></tr>`).join('')}</tbody></table></div></div>`}
function currentRiskPoint(){return riskPointConfigs.find(x=>x.name===riskConfigState.point)||riskPointConfigs[0]}
function riskPointRows(){const level=riskConfigState.level;const rows=riskPointConfigs.filter(x=>level==='全部'||x.levels.includes(level)||x.levels.includes('全部'));return rows.map((x,i)=>`<tr draggable="true" data-index="${riskPointConfigs.indexOf(x)}" class="${x.name===riskConfigState.point?'active-row':''}"><td class="drag-handle" title="拖动排序">⋮⋮</td><td><b>${x.name}</b><small>${riskConfigState.type} · ${x.category}</small></td><td>${x.levels.join('、')}</td><td>${x.category}</td><td>${x.required}</td><td><button class="ticket-count">${x.measures.length}</button></td><td><span class="status done">${x.status}</span></td><td><button class="detail risk-select">配置措施</button><button class="danger-text risk-delete">删除</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">当前等级暂无风险点</td></tr>'}
function riskBoundMeasureRows(point=currentRiskPoint()){return point.measures.map((text,i)=>{const meta=riskMeasureMeta.find(m=>m.text===text)||{text,required:'是',stage:'作业前',levels:point.levels.join('、'),deletable:'否'};return `<tr draggable="true" data-index="${i}"><td class="drag-handle" title="拖动排序">⋮⋮</td><td>${i+1}</td><td>${meta.text}</td><td>${meta.required}</td><td>${meta.stage}</td><td>${meta.levels}</td><td>${meta.deletable}</td><td><button class="detail risk-edit">编辑</button><button class="danger-text risk-unbind">移除</button></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">暂无绑定措施</td></tr>'}
function riskPointDetail(){const p=currentRiskPoint();if(!p)return `<aside class="risk-detail-panel"><div class="empty">暂无风险点，请先新增风险点</div></aside>`;return `<aside class="risk-detail-panel"><div class="risk-detail-head"><div><span>风险点详情</span><h3>${p.name}</h3></div><button class="ghost" id="editRiskPoint">编辑风险点</button></div><div class="risk-meta-grid"><label>适用等级<b>${p.levels.join('、')}</b></label><label>风险类别<b>${p.category}</b></label><label>默认选中<b>${p.required}</b></label><label>状态<b>${p.status}</b></label></div><div class="risk-detail-tabs"><button class="${riskDetailTab==='measures'?'active':''}" data-detail-tab="measures">绑定安全措施</button><button class="${riskDetailTab==='rules'?'active':''}" data-detail-tab="rules">适用规则</button></div><div id="riskDetailBody">${riskDetailTab==='rules'?riskRulesBody(p):riskMeasuresBody(p)}</div></aside>`}
function riskMeasuresBody(p){return `<div class="risk-measure-toolbar"><span>作业步骤 → 主要安全风险 → 安全防范措施</span><button class="primary" id="addRiskMeasure">＋ 新增措施</button></div><div class="table-wrap compact"><table class="risk-measure-table"><thead><tr><th class="drag-col"></th><th>序号</th><th>安全防范措施</th><th>必选</th><th>适用阶段</th><th>适用等级</th><th>可删除</th><th>操作</th></tr></thead><tbody id="riskMeasureRows">${riskBoundMeasureRows(p)}</tbody></table></div>`}
function riskRulesBody(p){const r=p.rules;return `<div class="risk-rule-source"><div><b>规则来源</b><span>等级管控规则来自“作业类型配置”；风险点触发规则在本页维护，两者在申请端叠加执行。</span></div><button class="ghost" id="editRiskRules">维护风险点触发规则</button></div><div class="risk-rule-grid">${[['是否需要专项方案',r.scheme],['是否需要升级审批',r.upgrade],['是否需要现场监护',r.guard],['是否需要领导到场',r.leader],['作业票有效期',r.valid],['视频/照片要求',r.video]].map(x=>`<article><span>${x[0]}</span><b>${x[1]}</b></article>`).join('')}</div><div class="level-extra"><b>等级补充要求</b><p>系统申请端先按风险点自动带出措施，再叠加当前作业等级维护的审批、监管、留痕和有效期要求。</p></div>`}
function riskConfigView(){const types=configuredWorkTypes().filter(x=>jobLevelConfigs.some(v=>v[0]===x)||riskConfigTypes.includes(x));if(!types.includes(riskConfigState.type))riskConfigState.type=types[0]||'动火作业';const levels=['全部',...levelsForWorkType(riskConfigState.type)];if(!levels.includes(riskConfigState.level))riskConfigState.level='全部';return `<div class="risk-config mixed-risk-config"><div class="config-scope-bar"><label>业务模式<select><option>普通作业</option><option>作业计划</option><option>一件一案</option></select></label><span>绑定关系：业务模式 + 作业类型 + 作业等级 → 风险点 → 管控措施</span></div><div class="risk-type-tabs">${types.map(x=>`<button class="${x===riskConfigState.type?'active':''}" data-risk-type="${x}">${x}</button>`).join('')}</div><section class="risk-level-filter"><b>作业等级：</b>${levels.map(x=>`<button class="${x===riskConfigState.level?'active':''}" data-risk-level="${x}">${x}</button>`).join('')}<span>等级来源：作业类型配置</span></section><div class="risk-model-layout"><section class="risk-point-panel"><div class="risk-block-title"><b>风险点配置</b><span>风险点为核心对象，可标记适用等级；支持拖动排序和删除</span><button class="primary" id="addRiskPoint">＋ 新增风险点</button></div><div class="table-wrap compact"><table class="risk-point-table"><thead><tr><th class="drag-col"></th><th>风险点名称</th><th>适用等级</th><th>风险类别</th><th>必选</th><th>绑定措施数</th><th>状态</th><th>操作</th></tr></thead><tbody id="riskPointRows">${riskPointRows()}</tbody></table></div></section>${riskPointDetail()}</div></div>`}
