const planView=()=>`${cards([['计划总数',String(plans.length),'▥','当前计划'],['进行中',String(plans.filter(p=>p.status==='执行中').length),'▷','现场执行'],['审批中',String(plans.filter(p=>p.status==='审批中').length),'⌛','等待审批'],['已完成','9','✓','本月累计']])}<section class="panel plan-panel"><div class="plan-toolbar"><div><b>计划明细</b><span>列表</span></div><div class="plan-filters"><input id="planSearch" placeholder="搜索计划名称或编号"><select id="planType"><option value="">全部作业类型</option><option>检维修计划</option><option>专项作业计划</option><option>周期检查计划</option></select><select id="planStatus"><option value="">全部状态</option><option>草稿</option><option>审批中</option><option>执行中</option><option>已发布</option></select><button class="ghost" id="planReset">重置</button><button class="primary" id="newPlan">＋ 新建计划</button></div></div><div class="table-wrap"><table class="plan-table"><thead><tr><th>计划编号 / 名称</th><th>作业类型</th><th>作业地点</th><th>计划起止时间</th><th>负责人</th><th>状态</th><th>操作</th></tr></thead><tbody id="planRows"></tbody></table></div><footer class="pagination"><span>共 ${plans.length} 条记录</span><div><button disabled>‹</button><button class="current">1</button><button>›</button></div></footer></section>`;
const templateBuilderView=()=>`<div class="template-top panel"><b>作业票类型</b>${['断路作业','动土作业','吊装作业','盲板抽堵作业','临时用电作业','动火作业','高处作业','受限空间作业'].map((x,i)=>`<button class="${i===0?'active':''}">${x}</button>`).join('')}</div><div class="template-version panel"><div><b>初始版本</b><span>新版本（未激活）</span>${['版本 2','版本 4','版本 5','版本 6'].map((x,i)=>`<button class="${i===0?'active':''}">${x}</button>`).join('')}</div><div><button class="template-action">✎ 编辑模式</button><button class="template-action" data-feedback="模板已复制">▣ 复制</button><button class="template-action danger" data-feedback="已删除当前草稿版本">▱ 删除</button><button class="template-action" data-feedback="模板已启用">▷ 启动</button><button class="template-action" data-feedback="模板已导出">↗ 导出</button></div></div><section class="panel visual-editor"><div class="editor-head"><b>可视化编辑</b><div><button id="previewTemplate">预览</button><button class="primary" data-feedback="模板已保存">保存</button></div></div><div class="editor-layout"><aside class="component-library"><h3>组件库</h3><p>拖到中间画布区域</p><b>基础编辑</b><div>${['单行文本','多行文本','数字','日期时间','单选按钮','复选框组','下拉框','成员单选','部门多选','字符串文本'].map(x=>`<button>＋ ${x}</button>`).join('')}</div><b>高级编辑</b><div>${['图片','附件','地址','定位','子表单','手写签名'].map(x=>`<button>＋ ${x}</button>`).join('')}</div></aside><main class="template-canvas"><h3>编辑作业票</h3><div id="canvasFields">${['关联作业计划|下拉选择','作业申请单位|单位选择','涉及相关单位/部门|多选输入','作业地点|地址选择','作业负责人|人员选择','计划开始时间|日期时间','作业内容|多行文本'].map((x,i)=>{let a=x.split('|');return `<div class="canvas-field ${i===1?'selected':''}"><span>⋮⋮</span><label>${i>0?'<i>*</i> ':''}${a[0]}</label><div>${a[1]}</div></div>`}).join('')}</div></main><aside class="property-panel"><h3>属性配置</h3><div class="prop-tabs"><button class="active">字段属性</button><button>表单属性</button></div><label>字段标题<input value="作业申请单位"></label><label>字段类型<select><option>单位选择</option></select></label><label><input type="checkbox" checked> 必填字段</label><label>默认提示<input value="请选择作业申请单位"></label><hr><b>表单提交规则</b>${['所有必填项校验通过','关联作业计划时间未过期','作业地点未被其他作业占用','自动同步关联计划申请数据'].map(x=>`<label><input type="checkbox" checked> ${x}</label>`).join('')}</aside></div></section>`;
const standaloneConfig=i=>`<section class="panel standalone-config">${configBody(i)}</section>`;
const regularView=()=>`<form class="regular-work panel" id="regularWorkForm"><section><h3>作业基本信息</h3><div class="regular-grid"><label>关联施工项目<div class="inline-control"><input id="linkedProject" placeholder="暂未关联施工项目" readonly><button type="button" class="primary" id="linkProject">＋ 关联施工项目</button></div><small>关联后可作为施工项目验收依据。</small></label><label>作业等级<div class="radio-line"><input type="radio" checked> 维修作业 <span>化工企业检维修，包括全厂停车大检修、装置停车检修等。</span></div></label><label class="wide">作业内容<textarea maxlength="500" placeholder="填写作业内容"></textarea><em>0 / 500</em></label><label>作业内容附件<div><button type="button" class="upload-btn">上传文件</button><span class="file-name">未选择文件</span></div></label><label>作业方案<div><button type="button" class="upload-btn">上传文件</button><span class="file-name">未选择文件</span></div></label><label>计划开始时间<input type="datetime-local"></label><label>计划结束时间<input type="datetime-local"></label><label>关联作业票<div class="inline-control"><input id="linkedTicket" placeholder="暂未关联作业票" readonly><button type="button" class="primary" id="linkTicket">＋ 关联作业票</button></div></label><label>选择监控设备<select><option>请选择</option><option>BKQ-001 · 4号楼焊接区</option><option>BKQ-005 · 粗破站高处作业区</option></select><small>选择后请携带设备前往现场，作业期间保留视频数据。</small></label></div></section><section><h3>作业相关单位、人员及地点</h3><div class="regular-grid two-col"><label>作业单位<select><option>请选择单位</option><option>齐大山铁矿</option><option>东鞍山铁矿</option></select></label><label>作业负责人<select><option>请选择成员</option><option>王安全</option><option>张建国</option></select></label><label>作业所在单位<select><option>东鞍山烧结厂</option></select></label><label>作业所在单位负责人<select><option>王主任</option></select></label><label>安全交底人<select><option>安全生产鞍钢项目</option></select></label><label class="split-select">作业单位监护人<select><option>安全生产鞍钢项目</option></select><span>属地单位监护人</span><select><option>殷血鬼</option></select></label><label class="wide">其他相关人员<textarea maxlength="500" placeholder="如需补充外部作业相关其他人，可填写相关信息。"></textarea></label><label>作业地点及部位<input placeholder="填写作业地点及部位"></label><label>地图标点<input placeholder="选择地图标点"></label></div></section><section><div class="section-head"><h3>作业人员</h3><button type="button" class="primary" id="addWorker">＋ 新增</button></div><div class="table-wrap"><table class="worker-table"><thead><tr><th>序号</th><th>姓名</th><th>岗位</th><th>部门</th><th>单位</th><th>操作</th></tr></thead><tbody id="workerRows"><tr><td>1</td><td>安全生产鞍钢项目</td><td>作业人员</td><td>安全管理部</td><td>鞍钢集团矿业有限公司</td><td><button type="button" class="detail remove-worker">移除</button></td></tr></tbody></table></div></section><section><h3>审批流程</h3><div class="approval-config"><b>作业审批节点</b><span>审批人</span><label>○ 作业负责人意见<select><option>请选择成员</option></select></label><label>○ 所在单位意见<select><option>王主任</option></select></label><b>验收审批节点</b><span>审批人</span><label>○ 完工验收意见<select><option>请选择成员</option></select></label></div></section><section><h3>抄送通知</h3><label class="copy-line">抄送成员<select><option>选择需要抄送通知的成员</option><option>李检查</option><option>张巡查</option></select></label></section><footer class="regular-actions"><button type="button" class="ghost" id="cancelRegular">取消</button><button type="submit" class="primary">提交</button></footer></form>`;
const templateCenterView=page=>`<div class="template-center-host"><iframe title="作业设计中心" src="template-center/index.html?embed=1&page=${page}&v=20260903"></iframe></div>`;
const views={overview:['安全作业一张图','全域作业态势与风险预警',overviewView],todo:['我的待办','集中处理待审批、待验收与抄送事项',todoView],plans:['作业计划','统筹计划周期、责任单位与关联作业票',planView],onecase:['一件一案','单项作业实施方案、风险措施与全过程确认',oneCaseView],regular:['常规作业','常规作业申请与审批配置',regularView],cross:['交叉作业','多单位同一区域作业风险管控',crossView],major:['危大工程','危大工程专项方案与施工过程管理',majorView],surveillance:['布控球管理','移动视频布控设备、在线状态与作业现场画面管理',surveillanceView],monitor:['智能监测','作业环境与设备状态实时感知',monitorView],alarms:['告警管理','统一受理设备、环境和人员行为告警',alarmsView],hazards:['隐患排查','隐患发现、整改与验收闭环管理',hazardView],analysis:['辅助分析','全部单位 · 作业数据统计分析',analysisView],templatecenter:['作业模板中心','统一设计作业申请表单、列表与审批流程',()=>templateCenterView('center')],templatedrafts:['设计草稿','继续编辑尚未发布的作业模板',()=>templateCenterView('drafts')],templateversions:['发布记录','查看作业模板版本和发布状态',()=>templateCenterView('versions')],config:['参数配置','作业类型、风险内容与安全交底配置',configView]};
function openView(key,nav){document.querySelector('.sidebar a.active')?.classList.remove('active');nav?.classList.add('active');if(key==='jobs'){title.textContent=activeWorkGroup;subtitle.textContent=`统一管理${activeWorkGroup}申请、审批、执行与验收全过程`;content.innerHTML=jobHome;configureJobGroupPage();setupJobs()}else{let v=views[key];title.textContent=v[0];subtitle.textContent=v[1];content.innerHTML=v[2]();injectBreadcrumb(key);setupDynamic(key)}setupCommonButtons();document.querySelector('.sidebar').classList.remove('open')}
function setupDynamic(key){if(key==='todo')setupTodoBoard();if(key==='plans')setupPlans();if(key==='onecase')setupOneCases();if(['cross','major'].includes(key)){document.querySelectorAll('.new-ticket').forEach(b=>b.onclick=showNewJob);setupWorkTypeTags();document.querySelectorAll('.rules button').forEach(b=>b.onclick=showCrossRecords);if(key==='major')document.querySelectorAll('.data-panel tbody .detail').forEach((b,i)=>b.onclick=()=>showMajorDetail(i))}if(key==='hazards'){document.querySelectorAll('.hazard-detail').forEach(b=>b.onclick=()=>showHazardDetail(hazardsData[+b.dataset.index]));document.querySelector('.hazard-filter .primary').onclick=showNewHazard}if(key==='config')setupConfig();if(key==='approval')setupConfigActions();if(key==='formbuilder')setupTemplateBuilder();if(key==='surveillance'){document.querySelector('#addCamera').onclick=showNewCamera;document.querySelectorAll('.camera-live').forEach(b=>b.onclick=()=>toast('正在连接布控球实时视频'));document.querySelectorAll('.camera-card .ghost').forEach((b,i)=>b.onclick=()=>showCameraConfig(i))}if(key==='alarms')document.querySelectorAll('.alarm-handle').forEach(b=>b.onclick=()=>showAlarm(+b.dataset.index))}

function todoJob(r){const type=r[2].replace('/','');return {id:r[0],name:r[1],content:r[1],type:type.replace(/一级|二级|三级|特级|高风险|一般风险/g,''),level:r[2],risk:r[2].includes('高风险')?'高风险':'一般风险',area:'鞍钢集团矿业有限公司 · 东鞍山烧结厂',time:`${r[3]} — ${r[4]}`,start:r[3],end:r[4],owner:r[5],workUnit:'鞍钢集团矿业有限公司',applyTime:r[7],status:r[6]}}
function todoActionLabel(state,progress){if(state==='approval')return '作业审批';if(state==='risk')return '风险评估';if(state==='site')return '提交验收';if(state==='accept')return '验收审批';if(progress.includes('安全措施'))return '安全措施确认';if(progress.includes('接收'))return '接收交底';if(progress.includes('交底'))return '安全交底';if(progress.includes('审批'))return '作业审批';return '气体检测'}
function todoProgressClass(progress){if(progress.includes('审批'))return 'warn';if(progress.includes('现场')||progress.includes('交底')||progress.includes('接收'))return 'ok';if(progress.includes('气体'))return 'blue';return 'cyan'}
function renderTodoRow(r){const action=todoActionLabel(todoState,r[6]);return `<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td><span class="time-mark start">起</span>${r[3]}<br><span class="time-mark end">末</span>${r[4]}</td><td><b>${r[5]}</b><small>鞍钢集团矿业有限公司</small></td><td><b>安全生产鞍钢项目</b><small>鞍钢集团矿业有限公司</small></td><td><span class="todo-progress ${todoProgressClass(r[6])}">${r[6]}</span></td><td>${r[7]}</td><td><div class="todo-actions"><button class="todo-action" data-action="detail" data-id="${r[0]}">作业详情</button><button class="todo-action" data-action="${action}" data-id="${r[0]}">${action}</button></div></td></tr>`}
function setupTodoBoard(){const body=document.querySelector('#todoRows'),search=document.querySelector('#todoSearch'),type=document.querySelector('#todoTypeFilter'),crumb=document.querySelector('#todoCrumb'),total=document.querySelector('#todoTotal');if(!body)return;const render=()=>{const q=search.value.trim(),t=type.value;document.querySelectorAll('[data-todo]').forEach(b=>b.classList.toggle('active',b.dataset.todo===todoState));crumb.textContent=todoTabs.find(x=>x[0]===todoState)[1];const data=(todoRows[todoState]||[]).filter(r=>(!t||r[2].includes(t.replace('作业','')))&&(!q||r.join('').includes(q)));body.innerHTML=data.map(renderTodoRow).join('')||'<tr><td colspan="9" class="empty">暂无待办数据</td></tr>';total.textContent=`共 ${data.length} 条`};document.querySelectorAll('[data-todo]').forEach(b=>b.onclick=()=>{todoState=b.dataset.todo;search.value='';type.value='';render()});search.oninput=render;type.onchange=render;body.onclick=e=>{const b=e.target.closest('[data-action]');if(!b)return;const row=(todoRows[todoState]||[]).find(r=>r[0]===b.dataset.id);handleTodoAction(b.dataset.action,row)};render()}
function handleTodoAction(action,row){if(!row)return;const job=todoJob(row);if(action==='detail')return showJobDetail(job);const map={作业审批:'作业审批意见',风险评估:'风险评估确认',安全措施确认:'安全措施确认',气体检测:'气体检测记录',接收交底:'接收安全交底',安全交底:'安全交底确认',提交验收:'提交完工验收',验收审批:'验收审批意见'};modal.innerHTML=`<div class="modal-card compact-modal"><button class="close">×</button><h3>${map[action]||action}</h3><p><b>${job.id}</b>　${job.name}</p><div class="detail-grid"><span>作业类型/等级</span><b>${job.level}</b><span>计划时间</span><b>${job.time}</b><span>责任人</span><b>${job.owner}</b><span>当前节点</span><b>${job.status}</b></div><label class="modal-note">处理意见<textarea placeholder="请输入处理意见或补充说明"></textarea></label><div class="modal-actions"><button class="ghost">取消</button><button class="primary">确定</button></div></div>`;modal.classList.add('open');modal.setAttribute('aria-hidden','false');modal.querySelector('.close').onclick=()=>modal.classList.remove('open');modal.querySelector('.ghost').onclick=()=>modal.classList.remove('open');modal.querySelector('.primary').onclick=()=>{modal.classList.remove('open');toast(`${action}已提交`)}}

function setupOneCases(){const rows=document.querySelector('#oneCaseRows'),search=document.querySelector('#oneCaseSearch'),risk=document.querySelector('#oneCaseRisk'),status=document.querySelector('#oneCaseStatus');const render=()=>{const q=search.value.trim();const visible=oneCases.filter(x=>(!q||`${x.id}${x.name}${x.project}`.includes(q))&&(!risk.value||x.level===risk.value)&&(!status.value||x.status===status.value));rows.innerHTML=visible.map(x=>{const i=oneCases.indexOf(x);return `<tr><td><b>${x.name}</b><small>${x.id}</small></td><td>${x.project}</td><td><div class="case-tags">${x.types.map(t=>`<span>${t}</span>`).join('')}</div></td><td><span class="risk ${x.level==='A级风险'?'high':x.level==='B级风险'?'mid':'low'}">${x.level}</span></td><td>${x.area}</td><td>${x.owner}</td><td><span class="status ${x.status==='编制中'?'pending':x.status==='已批准'?'done':'running'}">${x.status}</span></td><td><button class="detail one-case-detail" data-index="${i}">详情 ›</button></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">没有符合条件的一件一案</td></tr>';document.querySelectorAll('.one-case-detail').forEach(b=>b.onclick=()=>showOneCaseDetail(oneCases[+b.dataset.index]))};search.oninput=render;risk.onchange=render;status.onchange=render;document.querySelector('#oneCaseReset').onclick=()=>{search.value='';risk.value='';status.value='';render()};document.querySelector('#newOneCase').onclick=showNewOneCase;render()}
function setupPlans(){const rows=document.querySelector('#planRows'),search=document.querySelector('#planSearch'),type=document.querySelector('#planType'),status=document.querySelector('#planStatus');const render=()=>{const q=search.value.trim();const visible=plans.filter(p=>(!q||`${p.id}${p.name}`.includes(q))&&(!type.value||p.type===type.value)&&(!status.value||p.status===status.value));rows.innerHTML=visible.map(p=>{const i=plans.indexOf(p);return `<tr><td><b>${p.name}</b><small>${p.id}</small></td><td>${p.type}</td><td>${p.area}</td><td>${p.time}</td><td>${p.owner}</td><td><span class="status ${p.status==='草稿'?'pending':p.status==='已发布'?'done':'running'}">${p.status}</span></td><td><button class="detail plan-detail" data-index="${i}">详情 ›</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">没有符合条件的作业计划</td></tr>';document.querySelectorAll('.plan-detail').forEach(b=>b.onclick=()=>showPlanDetail(plans[+b.dataset.index]))};search.oninput=render;type.onchange=render;status.onchange=render;document.querySelector('#planReset').onclick=()=>{search.value='';type.value='';status.value='';render()};document.querySelector('#newPlan').onclick=showNewPlan;render()}

function setupCommonButtons(){content.querySelectorAll('.ghost').forEach(b=>{if(b.textContent.includes('导出'))b.onclick=()=>toast('导出任务已创建，文件正在生成')});content.querySelectorAll('.date').forEach(b=>b.onclick=()=>toast('日期选择器已展开：2026-08-18'));content.querySelectorAll('.pagination button:not([disabled])').forEach(b=>b.onclick=()=>{document.querySelector('.pagination .current')?.classList.remove('current');if(/^\d+$/.test(b.textContent.trim()))b.classList.add('current');toast(`已切换至第 ${/^\d+$/.test(b.textContent.trim())?b.textContent.trim():'下一'} 页`)})}
function setupWorkTypeTags(){document.querySelectorAll('.work-type-tags').forEach(group=>group.querySelectorAll('button:not(.more-work-types)').forEach(btn=>btn.onclick=()=>{group.querySelector('.active')?.classList.remove('active');btn.classList.add('active');const name=btn.querySelector('span')?.textContent.trim()||btn.textContent.trim();selectedJobType=name.includes('作业')?name:name+'作业';const create=document.querySelector('#newJob');if(create)create.textContent=`＋ 新建${selectedJobType}`;group.closest('.work-template-switch').querySelector('.template-context strong')&&(group.closest('.work-template-switch').querySelector('.template-context strong').textContent=selectedJobType);toast(`已选择${selectedJobType}模板`)}));document.querySelectorAll('.more-work-types').forEach(b=>b.onclick=()=>toast('更多类型：盲板抽堵、支护、探放水、采空区治理等'))}
function setupConfig(){document.querySelectorAll('[data-config]').forEach(b=>b.onclick=()=>{document.querySelector('[data-config].active')?.classList.remove('active');b.classList.add('active');document.querySelector('#configBody').innerHTML=configBody(+b.dataset.config);setupConfigActions()});setupConfigActions()}
function setupConfigActions(){setupRiskConfig();setupWorkTypeSettings();setupAdvancedConfig();document.querySelector('#addFlowNode')?.addEventListener('click',()=>{const canvas=document.querySelector('.flow-canvas');canvas?.querySelector('.end')?.insertAdjacentHTML('beforebegin','<em>→</em><div class="flow-node"><i>+</i><b>新增审批节点</b><span>待配置审批人</span></div>');toast('已添加审批节点，可继续配置审批人')});document.querySelector('#addField')?.addEventListener('click',()=>{document.querySelector('#fieldList').insertAdjacentHTML('beforeend','<div class="field-row"><span>⋮⋮</span><b>新增字段</b><i>单行文本</i><em>选填</em><button>删除</button></div>');toast('已添加一个自定义字段')});document.querySelector('#fieldList')?.addEventListener('click',e=>{if(e.target.tagName==='BUTTON'){e.target.closest('.field-row').remove();toast('字段已删除')}});document.querySelectorAll('.setting label button').forEach(b=>b.onclick=()=>{b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');toast('状态修改成功')});document.querySelectorAll('.jobtype-tabs button').forEach(b=>b.onclick=()=>{b.parentElement.querySelector('.active')?.classList.remove('active');b.classList.add('active');toast(`已切换至${b.textContent}配置`)});document.querySelectorAll('.config-toolbar .primary:not(#addGas):not(#addJobLevel):not(#sortJobLevel)').forEach(b=>b.onclick=()=>showConfigEditor('新增配置'));document.querySelectorAll('.config-table .detail').forEach(b=>b.onclick=()=>showConfigEditor('编辑配置'));document.querySelectorAll('.config-table .danger-text').forEach(b=>b.onclick=()=>{b.closest('tr').remove();toast('该配置已删除')});document.querySelectorAll('.custom-builder aside button').forEach(b=>b.onclick=()=>{document.querySelector('#fieldList')?.insertAdjacentHTML('beforeend',`<div class="field-row"><span>⋮⋮</span><b>${b.textContent.replace('＋ ','')}</b><i>自定义字段</i><em>选填</em><button>删除</button></div>`);toast('字段已加入表格')})}
function setupWorkTypeSettings(){const table=document.querySelector('.work-type-setting');if(!table)return;table.querySelector('#addWorkTypeGroup').onclick=()=>showWorkTypeDrawer();table.onclick=e=>{const row=e.target.closest('tr');if(!row)return;const gi=+row.dataset.group,child=row.dataset.child===undefined?null:+row.dataset.child;if(e.target.closest('.tree-toggle')){row.closest('tbody').classList.toggle('collapsed');return}if(e.target.closest('.add-work-child'))return showWorkTypeDrawer(gi);if(e.target.closest('.edit-work-type'))return showWorkTypeDrawer(gi,child,true);if(e.target.closest('.delete-work-type')){if(child===null)workTypeHierarchy.splice(gi,1);else workTypeHierarchy[gi].children.splice(child,1);syncWorkTypeConfig();document.querySelector('#configBody').innerHTML=generalConfigView();setupConfigActions();toast('作业类型配置已删除并同步')}}}
function showWorkTypeDrawer(groupIndex=null,childIndex=null,editing=false){document.querySelector('.config-drawer-layer')?.remove();const isChild=groupIndex!==null&&(childIndex!==null||!editing),current=editing?(childIndex===null?workTypeHierarchy[groupIndex].name:workTypeHierarchy[groupIndex].children[childIndex]):'';document.body.insertAdjacentHTML('beforeend',`<div class="config-drawer-layer"><button class="config-drawer-mask"></button><aside class="config-drawer"><header><b>▶ ${editing?'编辑':isChild?'新增二级':'新增一级'}作业类型</b><button class="config-drawer-close">×</button></header><div class="config-drawer-body"><label><span><i>*</i> 节点名称</span><input id="workTypeName" value="${current}" placeholder="请输入作业类型名称"></label>${isChild?`<label><span>所属一级节点</span><input value="${workTypeHierarchy[groupIndex].name}" disabled></label>`:''}<p class="drawer-help">系统目前只支持一级、二级节点。保存后同步更新作业管理菜单与作业模板中心。</p></div><footer><button class="ghost config-drawer-cancel">取消</button><button class="primary" id="saveWorkType">确定</button></footer></aside></div>`);const layer=document.querySelector('.config-drawer-layer'),close=()=>layer.remove();layer.querySelector('.config-drawer-mask').onclick=close;layer.querySelector('.config-drawer-close').onclick=close;layer.querySelector('.config-drawer-cancel').onclick=close;layer.querySelector('#saveWorkType').onclick=()=>{const name=layer.querySelector('#workTypeName').value.trim();if(!name)return toast('请输入节点名称');if(editing){childIndex===null?workTypeHierarchy[groupIndex].name=name:workTypeHierarchy[groupIndex].children[childIndex]=name}else if(isChild)workTypeHierarchy[groupIndex].children.push(name);else workTypeHierarchy.push({name,children:[]});syncWorkTypeConfig();close();document.querySelector('#configBody').innerHTML=generalConfigView();setupConfigActions();toast('作业类型已保存并同步菜单与模板')}}
function setupAdvancedConfig(){document.querySelector('#addGas')?.addEventListener('click',()=>showConfigDrawer('新增检测气体','gas'));document.querySelector('#gasRows')?.addEventListener('click',e=>{const row=e.target.closest('tr');if(!row)return;const i=+row.dataset.index;if(e.target.closest('.gas-edit'))showConfigDrawer('编辑检测气体','gas',i);if(e.target.closest('.gas-delete')){gasConfigs.splice(i,1);document.querySelector('#gasRows').innerHTML=gasRows();toast('检测气体已删除')}});document.querySelector('#addJobLevel')?.addEventListener('click',()=>showConfigDrawer('新增作业等级','level'));document.querySelector('#sortJobLevel')?.addEventListener('click',()=>toast('已进入作业等级排序模式'));document.querySelector('#jobLevelRows')?.addEventListener('click',e=>{const row=e.target.closest('tr');if(!row)return;const i=+row.dataset.index,node=e.target.closest('.node-count');if(node)return showApprovalNodeDialog(node.dataset.kind);if(e.target.closest('.level-edit'))showConfigDrawer('编辑作业等级','level',i);if(e.target.closest('.level-delete')){jobLevelConfigs.splice(i,1);document.querySelector('#jobLevelRows').innerHTML=jobLevelRows();toast('作业等级已删除')}});if(document.querySelector('#briefingRows'))document.querySelectorAll('.risk-type-tabs button,.briefing-head+.risk-measure-toolbar button').forEach(b=>b.onclick=()=>{b.parentElement.querySelector('.active')?.classList.remove('active');b.classList.add('active');toast(`已切换至${b.textContent}`)});document.querySelector('#addBriefing')?.addEventListener('click',()=>showConfigDrawer('新增安全交底内容','briefing'));document.querySelector('#briefingRows')?.addEventListener('click',e=>{const row=e.target.closest('tr');if(!row)return;const i=+row.dataset.index;if(e.target.closest('.briefing-edit'))showConfigDrawer('编辑安全交底内容','briefing',i);if(e.target.closest('.briefing-delete')){briefingConfigs.splice(i,1);document.querySelector('#briefingRows').innerHTML=briefingRows();toast('安全交底内容已删除')}});document.querySelectorAll('.finish-edit').forEach(b=>b.onclick=()=>showConfigDrawer('编辑结束确认标准','finish',+b.closest('tr').dataset.index))}
function showConfigDrawer(titleText,mode,index=null){document.querySelector('.config-drawer-layer')?.remove();let body='';if(mode==='gas'){const x=index===null?{name:'',unit:'',operator:'>',standard:''}:gasConfigs[index];body=`<label><span><i>*</i> 气体名称</span><input id="cfgName" value="${x.name}" placeholder="请输入气体名称"></label><label><span><i>*</i> 气体单位</span><input id="cfgUnit" value="${x.unit}" placeholder="请输入气体单位"></label><label><span><i>*</i> 合格标准</span><div class="standard-line"><select id="cfgOperator"><option ${x.operator==='>'?'selected':''}>&gt;</option><option ${x.operator==='≥'?'selected':''}>≥</option><option ${x.operator==='<'?'selected':''}>&lt;</option><option ${x.operator==='≤'?'selected':''}>≤</option><option ${x.operator==='介于'?'selected':''}>介于</option></select><input id="cfgStandard" value="${x.standard}" placeholder="请输入"></div></label>`}else if(mode==='level'){const x=index===null?['动火作业','','','否','0','0','0']:jobLevelConfigs[index];body=`<label><span><i>*</i> 作业类型</span><select id="cfgType">${riskConfigTypes.map(v=>`<option ${v===x[0]?'selected':''}>${v}</option>`).join('')}</select></label><label><span>作业等级</span><input id="cfgLevel" value="${x[1]}" placeholder="请输入作业等级"></label><label><span>定义</span><textarea id="cfgDefinition" placeholder="请输入文本定义">${x[2]}</textarea></label><label><span><i>*</i> 必须上传作业方案</span><div class="radio-row"><label><input type="radio" name="scheme"> 是</label><label><input type="radio" name="scheme" checked> 否</label></div></label><label><span><i>*</i> 作业票最长有效期</span><div class="unit-line"><input id="cfgHours" type="number" value="${parseInt(x[4])||0}"><b>小时</b></div></label><div class="node-sections"><div><b>作业审批节点（支持节点拖拽排序）</b><button type="button" class="ghost add-node-dialog" data-kind="作业审批节点">新增</button><div class="node-empty">暂无数据</div></div><div><b>验收审批节点（支持节点拖拽排序）</b><button type="button" class="ghost add-node-dialog" data-kind="验收审批节点">新增</button><div class="node-empty">暂无数据</div></div></div>`}else{const value=mode==='briefing'?(index===null?'':briefingConfigs[index]):finishStandards[index][1];body=`<label><span><i>*</i> ${mode==='briefing'?'安全交底内容':'结束确认标准'}</span><div class="drawer-textarea"><textarea id="cfgText" maxlength="300" placeholder="请输入内容">${value}</textarea><small><b id="cfgCount">${value.length}</b> / 300</small></div></label>`}document.body.insertAdjacentHTML('beforeend',`<div class="config-drawer-layer"><button class="config-drawer-mask"></button><aside class="config-drawer"><header><b>▶ ${titleText}</b><button class="config-drawer-close">×</button></header><div class="config-drawer-body">${body}</div><footer><button class="ghost config-drawer-cancel">取消</button><button class="primary" id="saveConfigDrawer">确定</button></footer></aside></div>`);const layer=document.querySelector('.config-drawer-layer'),close=()=>layer.remove();layer.querySelector('.config-drawer-mask').onclick=close;layer.querySelector('.config-drawer-close').onclick=close;layer.querySelector('.config-drawer-cancel').onclick=close;layer.querySelector('#cfgText')?.addEventListener('input',e=>layer.querySelector('#cfgCount').textContent=e.target.value.length);layer.querySelectorAll('.add-node-dialog').forEach(b=>b.onclick=()=>showApprovalNodeDialog(b.dataset.kind));layer.querySelector('#saveConfigDrawer').onclick=()=>{if(mode==='gas'){const name=layer.querySelector('#cfgName').value.trim(),unit=layer.querySelector('#cfgUnit').value.trim(),standard=layer.querySelector('#cfgStandard').value.trim();if(!name||!unit||!standard)return toast('请完整填写气体名称、单位和合格标准');const data={name,unit,operator:layer.querySelector('#cfgOperator').value,standard};index===null?gasConfigs.push(data):gasConfigs[index]=data}else if(mode==='level'){const data=[layer.querySelector('#cfgType').value,layer.querySelector('#cfgLevel').value||'—',layer.querySelector('#cfgDefinition').value||'待补充','否',`${layer.querySelector('#cfgHours').value||0}小时`,'0','0'];index===null?jobLevelConfigs.push(data):jobLevelConfigs[index]=data}else{const text=layer.querySelector('#cfgText').value.trim();if(!text)return toast('请输入内容');if(mode==='briefing')index===null?briefingConfigs.push(text):briefingConfigs[index]=text;else finishStandards[index][1]=text}close();document.querySelector('#configBody').innerHTML=configBody(mode==='gas'?0:mode==='level'?1:mode==='briefing'?3:4);setupConfigActions();toast(`${titleText.replace('新增','').replace('编辑','')}保存成功`)}}
function showApprovalNodeDialog(kind){document.querySelector('.node-dialog-layer')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="node-dialog-layer"><section class="node-dialog"><header><b>● 新增${kind}</b><button class="node-dialog-close">×</button></header><div><label><span><i>*</i> 审批节点</span><input id="nodeName" placeholder="请输入审批节点"></label><label><span><i>*</i> 审批人</span><select><option>自定义成员</option><option>作业负责人</option><option>所在单位负责人</option><option>安全管理部门</option></select></label><label><span><i>*</i> 现场照片</span><div class="radio-row"><label><input type="radio" name="photo"> 必填</label><label><input type="radio" name="photo" checked> 非必填</label></div></label></div><footer><button class="ghost node-dialog-cancel">取消</button><button class="primary" id="saveNode">提交</button></footer></section></div>`);const layer=document.querySelector('.node-dialog-layer'),close=()=>layer.remove();layer.querySelector('.node-dialog-close').onclick=close;layer.querySelector('.node-dialog-cancel').onclick=close;layer.querySelector('#saveNode').onclick=()=>{if(!layer.querySelector('#nodeName').value.trim())return toast('请输入审批节点');close();toast(`${kind}已新增`)}}
function refreshRiskConfig(msg){document.querySelector('#configBody').innerHTML=riskConfigView();setupConfigActions();if(msg)toast(msg)}
function setupRiskConfig(){const root=document.querySelector('.risk-config');if(!root)return;root.querySelectorAll('[data-risk-type]').forEach(b=>b.onclick=()=>{riskConfigState.type=b.dataset.riskType;riskConfigState.level='全部';refreshRiskConfig(`已切换至${b.textContent}配置`)});root.querySelectorAll('[data-risk-level]').forEach(b=>b.onclick=()=>{riskConfigState.level=b.dataset.riskLevel;refreshRiskConfig(`已切换至${b.textContent}等级适用范围`)});root.querySelectorAll('[data-detail-tab]').forEach(b=>b.onclick=()=>{riskDetailTab=b.dataset.detailTab;refreshRiskConfig(`已切换至${b.textContent}`)});root.querySelector('#editRiskPoint')?.addEventListener('click',()=>showRiskPointDrawer(riskPointConfigs.indexOf(currentRiskPoint())));root.querySelector('#editRiskRules')?.addEventListener('click',()=>showRiskRuleDrawer());root.querySelector('#addRiskPoint')?.addEventListener('click',()=>showRiskPointDrawer());root.querySelector('#addRiskMeasure')?.addEventListener('click',()=>showRiskMeasureDrawer());root.querySelector('#riskPointRows')?.addEventListener('click',e=>{const row=e.target.closest('tr');if(!row)return;const index=+row.dataset.index;if(e.target.closest('.risk-delete')){const removed=riskPointConfigs.splice(index,1)[0];if(removed?.name===riskConfigState.point)riskConfigState.point=riskPointConfigs[0]?.name||'';refreshRiskConfig('风险点已删除');return}riskConfigState.point=riskPointConfigs[index].name;riskDetailTab='measures';refreshRiskConfig(e.target.closest('.risk-select')?'已打开风险点措施配置':'已切换风险点详情')});root.querySelector('#riskMeasureRows')?.addEventListener('click',e=>{const row=e.target.closest('tr');if(!row)return;const index=+row.dataset.index,p=currentRiskPoint();if(e.target.closest('.risk-unbind')){p.measures.splice(index,1);refreshRiskConfig('安全措施已从风险点移除');return}if(e.target.closest('.risk-edit'))showRiskMeasureDrawer(index)});setupRiskDrag()}
function setupRiskDrag(){let source=null;document.querySelectorAll('#riskPointRows tr[draggable="true"]').forEach(el=>{el.ondragstart=()=>{source=el;el.classList.add('dragging')};el.ondragover=e=>{e.preventDefault();el.classList.add('drag-over')};el.ondragleave=()=>el.classList.remove('drag-over');el.ondrop=e=>{e.preventDefault();if(!source||source===el)return;const from=+source.dataset.index,to=+el.dataset.index,item=riskPointConfigs.splice(from,1)[0];riskPointConfigs.splice(to,0,item);refreshRiskConfig('风险点顺序已更新')};el.ondragend=()=>{el.classList.remove('dragging');document.querySelectorAll('#riskPointRows tr').forEach(x=>x.classList.remove('drag-over'))}});document.querySelectorAll('#riskMeasureRows tr[draggable="true"]').forEach(el=>{el.ondragstart=()=>{source=el;el.classList.add('dragging')};el.ondragover=e=>{e.preventDefault();el.classList.add('drag-over')};el.ondragleave=()=>el.classList.remove('drag-over');el.ondrop=e=>{e.preventDefault();if(!source||source===el)return;const p=currentRiskPoint(),from=+source.dataset.index,to=+el.dataset.index,item=p.measures.splice(from,1)[0];p.measures.splice(to,0,item);refreshRiskConfig('绑定安全措施顺序已更新')};el.ondragend=()=>{el.classList.remove('dragging');document.querySelectorAll('#riskMeasureRows tr').forEach(x=>x.classList.remove('drag-over'))}})}
function showRiskPointDrawer(index=null){document.querySelector('.risk-drawer-layer')?.remove();const available=levelsForWorkType(riskConfigState.type),p=index===null?{name:'',levels:[],category:'',required:'是',status:'启用',measures:[],rules:{scheme:'按等级要求判断',upgrade:'按现场风险判断',guard:'按现场风险判断',leader:'按等级要求判断',valid:'24小时',video:'按现场风险选择'}}:riskPointConfigs[index];document.body.insertAdjacentHTML('beforeend',`<div class="risk-drawer-layer"><button class="risk-drawer-mask" aria-label="关闭"></button><aside class="risk-drawer"><header><b>▶ ${index===null?'新增':'编辑'}风险点</b><button class="risk-drawer-close">×</button></header><div class="risk-drawer-body risk-point-form"><label><span><i>*</i> 风险点名称</span><input id="riskPointName" value="${p.name}" placeholder="请输入风险点名称"></label><label><span>风险类别</span><input id="riskPointCategory" value="${p.category}" placeholder="例如：吊装风险"></label><label><span><i>*</i> 适用等级</span><div class="risk-level-checks">${available.map(x=>`<label><input type="checkbox" name="riskPointLevel" value="${x}" ${p.levels.includes(x)||p.levels.includes('全部')?'checked':''}> ${x}</label>`).join('')}</div><small>可多选；选项来自“${riskConfigState.type}”的作业类型配置</small></label><label><span>默认选中</span><select id="riskPointRequired"><option ${p.required==='是'?'selected':''}>是</option><option ${p.required==='否'?'selected':''}>否</option></select></label><label><span>状态</span><select id="riskPointStatus"><option ${p.status==='启用'?'selected':''}>启用</option><option ${p.status==='停用'?'selected':''}>停用</option></select></label></div><footer><button class="ghost risk-drawer-cancel">取消</button><button class="primary" id="confirmRiskPoint">确定</button></footer></aside></div>`);const layer=document.querySelector('.risk-drawer-layer'),close=()=>layer.remove();layer.querySelector('.risk-drawer-mask').onclick=close;layer.querySelector('.risk-drawer-close').onclick=close;layer.querySelector('.risk-drawer-cancel').onclick=close;layer.querySelector('#confirmRiskPoint').onclick=()=>{const name=layer.querySelector('#riskPointName').value.trim(),levels=[...layer.querySelectorAll('[name="riskPointLevel"]:checked')].map(x=>x.value);if(!name)return toast('请输入风险点名称');if(!levels.length)return toast('请至少选择一个适用等级');const data={...p,name,category:layer.querySelector('#riskPointCategory').value.trim()||'现场风险',levels,required:layer.querySelector('#riskPointRequired').value,status:layer.querySelector('#riskPointStatus').value};index===null?riskPointConfigs.push(data):riskPointConfigs[index]=data;riskConfigState.point=name;close();refreshRiskConfig(index===null?'风险点已新增':'风险点已更新')}}
function showRiskRuleDrawer(){const p=currentRiskPoint(),r=p.rules;document.querySelector('.risk-drawer-layer')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="risk-drawer-layer"><button class="risk-drawer-mask"></button><aside class="risk-drawer"><header><b>▶ 维护风险点触发规则</b><button class="risk-drawer-close">×</button></header><div class="risk-drawer-body risk-point-form">${[['scheme','专项方案',r.scheme],['upgrade','升级审批',r.upgrade],['guard','现场监护',r.guard],['leader','领导到场',r.leader],['valid','作业票有效期',r.valid],['video','视频/照片要求',r.video]].map(x=>`<label><span>${x[1]}</span><input data-rule="${x[0]}" value="${x[2]}"></label>`).join('')}<p class="drawer-help">此处只维护风险点触发条件；审批节点、有效期等等级强制要求仍在“作业类型配置”维护。</p></div><footer><button class="ghost risk-drawer-cancel">取消</button><button class="primary" id="saveRiskRules">确定</button></footer></aside></div>`);const layer=document.querySelector('.risk-drawer-layer'),close=()=>layer.remove();layer.querySelector('.risk-drawer-mask').onclick=close;layer.querySelector('.risk-drawer-close').onclick=close;layer.querySelector('.risk-drawer-cancel').onclick=close;layer.querySelector('#saveRiskRules').onclick=()=>{layer.querySelectorAll('[data-rule]').forEach(x=>r[x.dataset.rule]=x.value.trim()||'无');close();refreshRiskConfig('风险点触发规则已更新')}}
