function showNewPlan(){
 title.textContent='新建作业计划';subtitle.textContent='创建独立作业计划并关联作业类型、负责人和现场位置';
 content.innerHTML=`<div class="plan-create-page"><div class="plan-create-breadcrumb"><button type="button" id="backToPlans">作业计划</button><span>›</span><b>新建作业计划</b></div><form id="planCreateForm"><section class="panel plan-create-section"><header><div><h2>计划基本信息</h2><p>计划编号将在提交创建时自动生成</p></div><span class="plan-page-badge">独立页面</span></header><div class="plan-create-grid"><label><span><i>*</i> 计划名称</span><input id="planName" placeholder="请输入计划名称"></label><label><span><i>*</i> 作业地点</span><select id="planArea"><option value="">请选择作业地点</option><option>二选车间</option><option>尾矿库</option><option>-320m 泵房</option><option>粗破站</option></select></label><label><span><i>*</i> 作业类型</span><select id="planWorkType"><option value="">请选择关联作业类型</option>${planWorkTypes.map(x=>`<option>${x}</option>`).join('')}</select></label><label><span><i>*</i> 负责人</span><select id="planOwner"><option value="">请选择负责人</option><option>张建国</option><option>刘志强</option><option>李明远</option><option>赵海峰</option></select></label><label><span><i>*</i> 计划开始时间</span><input id="planStart" type="datetime-local"></label><label><span><i>*</i> 计划结束时间</span><input id="planEnd" type="datetime-local"></label><label class="full"><span>作业内容</span><div class="plan-textarea-wrap"><textarea id="planContent" maxlength="200" placeholder="请输入简单的作业内容"></textarea><small><b id="planContentCount">0</b> / 200</small></div></label></div></section><section class="panel plan-create-section"><header><div><h2>现场关联信息</h2><p>按需关联监控设备，并在厂区地图中标记计划作业位置</p></div></header><div class="plan-create-grid"><label><span>监控设备</span><select id="planDevice"><option>暂不选择</option><option>BKQ-001 · 二选车间</option><option>BKQ-005 · 粗破站</option></select></label><label><span>地图标点</span><div class="plan-map-field"><input id="planMapPoint" placeholder="请选择地图标点" readonly><button type="button" class="ghost" id="choosePlanPoint">选择标点</button></div></label></div></section><footer class="plan-page-actions"><button type="button" class="ghost" id="cancelPlanCreate">取消</button><button type="submit" class="primary">提交创建</button></footer></form></div>`;
 const form=document.querySelector('#planCreateForm'),back=()=>openView('plans',document.querySelector('[data-view="plans"]'));
 document.querySelector('#backToPlans').onclick=back;document.querySelector('#cancelPlanCreate').onclick=back;
 document.querySelector('#planContent').oninput=e=>document.querySelector('#planContentCount').textContent=e.target.value.length;
 document.querySelector('#choosePlanPoint').onclick=()=>showPlanMapPicker(document.querySelector('#planMapPoint'));
 form.onsubmit=e=>{e.preventDefault();const name=document.querySelector('#planName').value.trim(),area=document.querySelector('#planArea').value,type=document.querySelector('#planWorkType').value,owner=document.querySelector('#planOwner').value,start=document.querySelector('#planStart').value,end=document.querySelector('#planEnd').value,mapPoint=document.querySelector('#planMapPoint').value;if(!name||!area||!type||!owner||!start||!end)return toast('请完整填写计划名称、地点、作业类型、负责人和计划时间');if(end<=start)return toast('计划结束时间必须晚于开始时间');plans.unshift({id:`JH${new Date().toISOString().slice(0,10).replaceAll('-','')}${String(plans.length+1).padStart(3,'0')}`,name,type,unit:'鞍钢集团矿业有限公司',area,time:`${start.replace('T',' ')} — ${end.replace('T',' ')}`,owner,status:'草稿',tickets:0,mapPoint});back();toast('作业计划创建成功')};
}
function showPlanMapPicker(target){document.querySelector('.plan-map-picker-layer')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="plan-map-picker-layer"><button class="plan-map-picker-mask" aria-label="关闭地图标点"></button><section class="plan-map-picker"><header><div><h2><i>●</i> 地图标点</h2><p>选择楼层后，在地图上点击确定作业位置</p></div><button class="plan-map-picker-close">×</button></header><div class="plan-map-tools"><label>楼栋/楼层 <select id="mapFloor"><option>厂区总图</option><option>二选车间 · 一层</option><option>二选车间 · 二层</option><option>粗破站 · 一层</option></select></label><span id="mapPointTip">尚未选择点位</span></div><div class="plan-point-map" id="planPointMap" role="button" aria-label="点击地图选择标点"><span>请在地图上点击撒点</span></div><footer><button class="ghost plan-map-cancel">取消</button><button class="primary" id="confirmPlanPoint" disabled>确定</button></footer></section></div>`);const picker=document.querySelector('.plan-map-picker-layer'),map=picker.querySelector('#planPointMap'),tip=picker.querySelector('#mapPointTip'),confirm=picker.querySelector('#confirmPlanPoint');let point=null;const close=()=>picker.remove();picker.querySelector('.plan-map-picker-mask').onclick=close;picker.querySelector('.plan-map-picker-close').onclick=close;picker.querySelector('.plan-map-cancel').onclick=close;picker.querySelector('#mapFloor').onchange=()=>{point=null;map.querySelector('.selected-map-pin')?.remove();tip.textContent='尚未选择点位';confirm.disabled=true};map.onclick=e=>{const rect=map.getBoundingClientRect(),x=Math.round((e.clientX-rect.left)/rect.width*100),y=Math.round((e.clientY-rect.top)/rect.height*100);point={x,y};map.querySelector('.selected-map-pin')?.remove();map.insertAdjacentHTML('beforeend',`<i class="selected-map-pin" style="left:${x}%;top:${y}%"><b></b></i>`);tip.textContent=`已选择点位：X ${x}% · Y ${y}%`;confirm.disabled=false};confirm.onclick=()=>{if(!point)return;target.value=`${picker.querySelector('#mapFloor').value}（X ${point.x}%，Y ${point.y}%）`;close();toast('地图标点已选择')}}
function handleJobAction(action,j,render){if(action==='detail')return showJobDetail(j);if(action==='copy')return copyJobToNew(j);if(action==='delete'){if(!confirm(`确认删除作业记录 ${j.id}？`))return;const idx=jobs.findIndex(x=>x.id===j.id);idx>-1?jobs.splice(idx,1):j.listStatus='已删除';toast('作业记录已删除');return render()}if(action==='terminate'){j.status='作废';j.listStatus='作废';toast('作业已终止并归入作废状态');return render()}if(action==='monitor')return showJobMonitor(j);if(action==='ticket')return showJobTicket(j);if(action==='smart')return openSmartDetectList(j);if(action==='guard')return showGuardRecords(j)}
function copyJobToNew(j){const limited=/有限|受限/.test(j.type);if(limited){jobWizardState.origin='jobs';jobWizardState.type='有限空间';title.textContent='申请作业票';subtitle.textContent='复制新增：请重新填写计划开始时间和计划结束时间';renderLimitedSpaceJobPage();document.querySelector('#limitedSpaceName')&&(document.querySelector('#limitedSpaceName').value=j.name);document.querySelector('#limitedJobContent')&&(document.querySelector('#limitedJobContent').value=j.content||j.name);document.querySelector('#workOwner')&&(document.querySelector('#workOwner').value=j.owner);document.querySelector('#belongUnit')&&(document.querySelector('#belongUnit').value=j.area.split(' · ')[0]||'');toast('已复制作业信息，计划时间请重新填写');return}jobWizardState.origin='jobs';jobWizardState.type=j.type;jobWizardState.types=[...new Set([...jobWizardState.types,j.type])];jobWizardState.step=0;title.textContent='新建作业票';subtitle.textContent='复制新增：请重新填写计划开始时间和计划结束时间';renderJobWizard();document.querySelector('#wizardJobName')&&(document.querySelector('#wizardJobName').value=j.name);document.querySelector('#wizardJobContent')&&(document.querySelector('#wizardJobContent').value=j.content||j.name);document.querySelector('#ownerText')&&(document.querySelector('#ownerText').textContent=j.owner);toast('已复制作业信息，计划时间请重新填写')}
function showJobMonitor(j){document.querySelector('#modalTitle').textContent='实时/回放监控 · '+j.id;document.querySelector('#modalBody').innerHTML=`<div class="job-monitor"><div class="monitor-screen"><span>▶</span><b>${j.area}</b><small>实时画面 / 历史回放</small></div><div class="modal-grid"><div><span>监控设备</span><b>BKQ-00${(j.id.length%5)+1}</b></div><div><span>在线状态</span><b>在线</b></div><div><span>录像时间</span><b>${j.time}</b></div><div><span>告警记录</span><b>0 条未处理</b></div></div></div>`;openModal();document.querySelector('.modal-actions .primary').textContent='打开回放'}
function showJobTicket(j){document.querySelector('#modalTitle').textContent='作业票 · '+j.id;document.querySelector('#modalBody').innerHTML=`<div class="job-ticket-print"><h3>安全作业票</h3><div class="modal-grid"><div><span>作业票编号</span><b>${j.id}</b></div><div><span>作业类型</span><b>${j.type}</b></div><div><span>作业等级</span><b>${j.level||j.risk}</b></div><div><span>作业内容</span><b>${j.content||j.name}</b></div><div><span>作业单位</span><b>${j.workUnit||'鞍钢集团矿业有限公司'}</b></div><div><span>负责人</span><b>${j.owner}</b></div><div><span>作业地点</span><b>${j.area}</b></div><div><span>计划时间</span><b>${j.time}</b></div></div><p>风险辨识、安全措施、审批意见和监护记录已汇总生成，可打印留档。</p></div>`;openModal();document.querySelector('.modal-actions .primary').textContent='打印作业票';document.querySelector('.modal-actions .primary').onclick=()=>{toast('已调起作业票打印');window.print&&window.print()}}
function openSmartDetectList(j){title.textContent='智能检测设备列表';subtitle.textContent=`${j.id} · ${j.name} 的气体检测、AI 识别和现场传感设备`;content.innerHTML=monitorView();setupDynamic('monitor');toast('已跳转智能检测设备列表')}
function showGuardRecords(j){document.querySelector('#modalTitle').textContent='智能监护清单 · '+j.id;document.querySelector('#modalBody').innerHTML=`<div class="guard-records">${['作业人员到岗核验','安全交底拍照留痕','气体检测结果确认','监护人员在岗识别','作业区域警戒线检查','完工清场确认'].map((x,i)=>`<div><i>${i<4?'✓':i+1}</i><b>${x}</b><span>${i<4?'已完成':'待确认'} · ${i<4?'2026-09-01 09:'+(10+i*6):'--'}</span></div>`).join('')}</div>`;openModal();document.querySelector('.modal-actions .primary').textContent='导出监护记录'}
function showAlarm(i){const names=['4号楼焊接区未检测到监护人员','扬尘浓度超过 150μg/m³','高处作业安全带佩戴异常','布控球离线超过 10 分钟'];document.querySelector('#modalTitle').textContent='告警详情 · GJ2026081800'+(i+1);document.querySelector('#modalBody').innerHTML=`<div class="alarm-detail-head"><span class="risk ${i<2?'high':'mid'}">${i<2?'高危告警':'中危告警'}</span><b>${names[i]}</b></div><div class="modal-grid"><div><span>告警来源</span><b>${i===1?'A2 扬尘监测':'BKQ-00'+(i+1)}</b></div><div><span>发生时间</span><b>2026-08-18 10:${25-i*4}</b></div><div><span>作业区域</span><b>${['4号楼焊接区','施工现场南侧','粗破站','井下泵房'][i]}</b></div><div><span>当前状态</span><b>${i===3?'已关闭':'待处理'}</b></div></div><div class="info-section"><h3>处置要求</h3><p>立即核实现场情况，通知作业负责人暂停相关作业，完成处置后上传现场照片并填写处置说明。</p><textarea class="alarm-note" placeholder="请输入处置说明"></textarea></div>`;openModal();document.querySelector('.modal-actions .primary').textContent=i===3?'查看处置记录':'提交处置'}
function showJobDetail(j){document.querySelector('#modalTitle').textContent=j.name;document.querySelector('#modalBody').innerHTML=`<div class="detail-tabs"><b>作业基本信息</b><span>风险评估</span><span>安全措施</span><span>作业审批</span><span>过程监测</span></div><div class="modal-grid"><div><span>作业编号</span><b>${j.id}</b></div><div><span>当前状态</span><b>${j.status}</b></div><div><span>作业类型</span><b>${j.type} · ${j.risk}</b></div><div><span>负责人</span><b>${j.owner}</b></div><div><span>作业区域</span><b>${j.area}</b></div><div><span>计划时间</span><b>${j.time}</b></div></div><div class="approval-timeline"><h3>审批进度</h3><div><i>✓</i><b>作业申请</b><span>${j.owner} · 08-17 16:20</span></div><div><i>✓</i><b>单位初审</b><span>单位负责人 · 08-17 17:05</span></div><div class="current"><i>3</i><b>安全审批</b><span>待安全管理部处理</span></div><div><i>4</i><b>现场验票</b><span>尚未开始</span></div></div>`;openModal()}
function showHazardDetail(h){document.querySelector('#modalTitle').textContent='隐患详情 · '+h.id;const info=`<div class="info-section"><h3>隐患基本信息</h3><div class="info-grid"><p><span>隐患单位</span>鞍钢集团矿业有限公司</p><p><span>整改责任人</span>影分身二 15567899876</p><p><span>隐患来源</span>人工上报-内部</p><p><span>隐患位置</span>${h.area}</p><p><span>检查人</span>${h.owner}</p><p><span>整改期限</span>${h.deadline}</p></div></div><div class="info-section"><h3>隐患详细信息</h3><p>隐患描述：${h.desc}</p><p>隐患分类：${h.type}</p><p>隐患等级：${h.risk}</p><div class="hazard-photo">现场照片<br><span>⚠</span></div></div><div class="info-section"><h3>检查信息</h3><p>检查类别：日常检查</p><p>法规依据：《安全生产隐患排查治理管理办法》</p><p>合规要求：发现隐患后立即设置警戒并限期完成整改。</p></div>`;const records=`<div class="rectify-record"><i>✓</i><div><b>隐患上报</b><p>${h.owner} 于 2026-08-18 09:12 完成隐患登记</p></div></div><div class="rectify-record"><i>2</i><div><b>下发整改</b><p>整改责任人已接收，期限 ${h.deadline}</p></div></div><div class="rectify-record pending"><i>3</i><div><b>整改验收</b><p>等待整改完成后发起验收</p></div></div>`;document.querySelector('#modalBody').innerHTML=`<div class="detail-tabs hazard-tabs"><button class="active" data-tab="info">隐患信息</button><button data-tab="records">隐患整改记录</button></div><div id="hazardDetailBody">${info}</div>`;openModal();document.querySelectorAll('.hazard-tabs button').forEach(t=>t.onclick=()=>{document.querySelector('.hazard-tabs .active')?.classList.remove('active');t.classList.add('active');document.querySelector('#hazardDetailBody').innerHTML=t.dataset.tab==='records'?records:info})}
function showNewJob(){document.querySelector('#modalTitle').textContent='申请作业票';document.querySelector('#modalBody').innerHTML=`<div class="form-steps"><b>1 基本信息</b><span>2 风险辨识</span><span>3 安全措施</span><span>4 提交审批</span></div><div class="form-grid"><label>作业名称<input placeholder="请输入作业名称"></label><label>作业类型<select><option>动火作业</option><option>高处作业</option><option>有限空间作业</option></select></label><label>作业区域<input placeholder="请选择作业区域"></label><label>负责人<input value="王安全"></label><label class="full">作业内容<textarea placeholder="请输入具体作业内容"></textarea></label></div>`;openModal();document.querySelector('.modal-actions .primary').textContent='下一步'}
function showPlanTickets(p){document.querySelector('#modalTitle').textContent=`关联作业票 · ${p.id}`;document.querySelector('#modalBody').innerHTML=p.tickets?`<div class="info-section"><h3>${p.name}</h3>${jobs.slice(0,Math.min(p.tickets,jobs.length)).map(j=>`<p><b>${j.id}</b>　${j.name}　<span class="status running">${j.status}</span></p>`).join('')}</div>`:'<div class="empty">当前计划尚未关联作业票，可在计划详情中新增关联。</div>';openModal();document.querySelector('.modal-actions .primary').textContent='新增关联作业票'}
function showCrossRecords(){document.querySelector('#modalTitle').textContent='交叉作业记录';document.querySelector('#modalBody').innerHTML=`<div class="info-section"><h3>当前识别到 2 组交叉作业</h3><p><b>二选车间检修区域</b>　动火作业 × 临时用电作业　<span class="risk high">高风险</span></p><p><b>尾矿库回水区域</b>　吊装作业 × 管道检修　<span class="risk mid">较大风险</span></p></div>`;openModal();document.querySelector('.modal-actions .primary').textContent='导出记录'}
function showMajorDetail(i){const names=['尾矿库回水管道吊装','破碎站高支模施工','-320m 泵房深基坑'];document.querySelector('#modalTitle').textContent='危大工程详情 · '+names[i];document.querySelector('#modalBody').innerHTML=`<div class="modal-grid"><div><span>工程编号</span><b>WD2026081800${i+1}</b></div><div><span>当前状态</span><b>${i?'施工中':'待审批'}</b></div><div><span>专项方案</span><b>已上传并完成专家论证</b></div><div><span>负责人</span><b>${['刘志强','赵海峰','李明远'][i]}</b></div></div><div class="info-section"><h3>施工管控要求</h3><p>施工前完成方案交底，关键工序旁站监督，验收合格后方可进入下一工序。</p></div>`;openModal();document.querySelector('.modal-actions .primary').textContent='查看专项方案'}
function showNewHazard(){document.querySelector('#modalTitle').textContent='新增隐患';document.querySelector('#modalBody').innerHTML=`<div class="form-grid"><label>隐患位置<input placeholder="请输入隐患位置"></label><label>隐患等级<select><option>一般隐患</option><option>重大隐患</option></select></label><label>整改责任人<input placeholder="请选择责任人"></label><label>整改期限<input type="date"></label><label class="full">隐患描述<textarea placeholder="请输入隐患描述"></textarea></label></div>`;openModal();document.querySelector('.modal-actions .primary').textContent='保存隐患'}
