function showConfigEditor(mode){document.querySelector('#modalTitle').textContent=mode;document.querySelector('#modalBody').innerHTML=`<div class="form-grid"><label>配置名称<input placeholder="请输入配置名称"></label><label>适用作业类型<select><option>动火作业</option><option>高处作业</option><option>吊装作业</option></select></label><label class="full">配置内容<textarea placeholder="请输入配置内容"></textarea></label></div>`;openModal();document.querySelector('.modal-actions .primary').textContent='保存配置'}
function openModal(){modal.classList.add('open');modal.setAttribute('aria-hidden','false')}function close(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.querySelector('.modal-actions').style.display='';document.querySelector('.modal-actions .primary').textContent='查看审批单';document.querySelector('.modal-actions .primary').onclick=defaultModalPrimaryAction}function toast(msg){let t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function defaultModalPrimaryAction(){const b=document.querySelector('.modal-actions .primary'),label=b.textContent.trim();if(label==='下一步'){const steps=[...document.querySelectorAll('.form-steps>*')],active=steps.findIndex(x=>x.tagName==='B'),next=Math.min(active+1,steps.length-1);steps.forEach((x,i)=>{const tag=i===next?'b':'span';if(x.tagName.toLowerCase()!==tag)x.outerHTML=`<${tag}>${x.textContent}</${tag}>`});toast(next===steps.length-1?'信息已校验，可提交审批':'已进入下一步，请继续完善信息')}else if(label.includes('提交')||label.includes('保存')){toast(`${label}成功`);setTimeout(close,500)}else if(label.includes('导出'))toast('导出任务已创建，文件正在生成');else toast(`已打开${label}内容`)}
