const receiveBriefingFlow=renderSafetyBriefingPage;renderSafetyBriefingPage=function(row){receiveBriefingFlow(row);const page=document.querySelector('.briefing-page'),submit=page?.querySelector('#submitBriefingBottom');if(!submit)return;submit.onclick=()=>{const wrap=submit.parentElement;submit.remove();wrap.insertAdjacentHTML('beforeend','<button class="primary" id="receiveBriefing">接收交底</button>');page.querySelector('#receiveBriefing').onclick=()=>renderReceiveBriefingPage(row)}};function renderReceiveBriefingPage(row){const job=todoJob(row);title.textContent='接收交底';subtitle.textContent='请阅读安全交底内容并确认接收';content.innerHTML=`<div class="page-breadcrumb">我的待办　/　安全措施　/　接收交底</div><section class="receive-briefing-page panel"><header class="briefing-head"><div><button class="ghost" id="backReceiveBriefing">← 返回安全交底</button><h2>接收交底</h2><p><b>${job.id}</b>　${job.name}</p></div></header><section class="briefing-section"><h3>作业基本信息</h3><div class="receive-info"><span>作业类型：${job.type}</span><span>作业等级：${job.level}</span><span>作业负责人：${job.owner}</span><span>作业区域：${job.area}</span><span>计划时间：${job.time}</span></div></section><section class="briefing-section"><h3>作业步骤</h3><ol class="receive-steps"><li>作业前检查作业区域及设备状态，确认安全条件。</li><li>按作业方案实施现场作业，严格执行操作规程。</li><li>作业完成后清理现场并确认，撤除警戒设施。</li></ol></section><section class="briefing-section"><h3>风险点及风险管控措施</h3><div class="receive-risks"><p><b>触电</b>　作业区域已隔离并设置警示标识，防护用品已核验。</p><p><b>火灾</b>　现场监护人员全程在岗，消防器材配置到位。</p><p><b>高处坠落</b>　确认作业平台及安全带等防护设施可靠。</p></div></section><section class="briefing-section"><h3>周边危险禁入区域告知</h3><p class="receive-notice">作业区域周边设置警戒线，非作业人员禁止进入；涉及交叉作业时应提前沟通并做好隔离。</p></section><section class="briefing-footer"><label><input type="checkbox" id="receiveChecked"> 我已阅读并知悉以上安全交底内容</label><label>接收交底人签字 <button class="signature-box">点击签字</button></label><div><button class="ghost" id="cancelReceive">取消</button><button class="primary" id="submitReceive">提交</button></div></section></section>`;content.querySelector('#backReceiveBriefing').onclick=()=>renderSafetyBriefingPage(row);content.querySelector('#cancelReceive').onclick=()=>openView('todo');content.querySelector('#submitReceive').onclick=()=>{if(!content.querySelector('#receiveChecked').checked)return toast('请先确认已阅读安全交底内容');toast('接收交底已提交');openView('todo')}}

/* 安全措施确认增强：多风险点分组、逐项留痕、现场照片和签字校验。 */
const safetyMeasureGroupedFlow=handleTodoAction;
handleTodoAction=function(action,row){
  if(action!=='安全措施确认')return safetyMeasureGroupedFlow(action,row);
  renderGroupedSafetyConfirmation(row);
};

function renderGroupedSafetyConfirmation(row){
  const job=todoJob(row);
  const groups=[
    {name:'受限空间窒息、中毒',level:'较大风险',measures:['办理受限空间作业许可，对作业过程中的风险进行识别并采取管控措施。','作业前执行“先通风、再检测、后作业”，检测合格后方可进入。','作业过程中持续进行气体检测和通风，现场监护人员全程在岗。','出入口通道保持畅通，无杂物堵塞，应急救援器材放置到位。']},
    {name:'触电',level:'一般风险',measures:['使用安全电压的防爆照明设备，潮湿容器内使用 12V 及以下电压。','电气线路采用剩余电流动作保护器，工器具使用前完成绝缘检查。']},
    {name:'物体打击、高处坠落',level:'一般风险',measures:['作业区域设置硬隔离和醒目警示标识，非作业人员禁止进入。','高处作业人员正确佩戴安全带，工器具采取防坠措施。']}
  ];
  modal.classList.remove('open');
  title.textContent='安全措施确认';
  subtitle.textContent='由现场安全人员逐项确认并签字';
  let number=0;
  content.innerHTML=`<div class="page-breadcrumb">我的待办　/　安全措施</div><section class="safety-confirm-page safety-grouped-page panel"><header class="safety-confirm-head"><div><button class="ghost" id="backSafetyTodo">← 返回待办</button><h2>安全措施确认</h2><p><b>${job.id}</b>　${job.name}　<span>${job.level}</span></p></div><div class="safety-head-actions"><button class="primary small" id="batchSafetyDone">批量已落实</button><button class="danger small" id="batchSafetyNA">批量不涉及</button></div></header><div class="safety-progress"><div><b id="safetyConfirmedCount">0</b> / <span id="safetyTotalCount">${groups.reduce((sum,g)=>sum+g.measures.length,0)}</span> 项已确认</div><span><i id="safetyProgressBar"></i></span><em id="safetyProgressText">请逐项确认安全措施落实情况</em></div><div class="safety-risk-groups">${groups.map((group,groupIndex)=>`<section class="safety-risk-group"><header><div><i>${groupIndex+1}</i><span><b>风险点：${group.name}</b><small>${group.level} · ${group.measures.length} 项措施</small></span></div><button class="ghost small safety-group-toggle">收起</button></header><div class="safety-confirm-list">${group.measures.map(measure=>{number+=1;return `<article data-index="${number-1}" data-status=""><div class="safety-measure-main"><span class="measure-number">${number}</span><p>${measure}</p><div class="safety-measure-actions"><button class="ghost safety-done">已落实</button><button class="ghost safety-na">不涉及</button></div></div><div class="safety-extra"></div></article>`}).join('')}</div></section>`).join('')}</div><section class="safety-sign"><div class="safety-confirmer"><span>现场确认人</span><b>安全生产鞍钢项目</b><small>现场安全人员</small></div><label>确认人签字 <button class="signature-box" id="safetySignature">✍ 点击签字</button></label><div><button class="ghost" id="cancelSafetyConfirm">取消</button><button class="primary" id="submitSafetyConfirm">提交</button></div></section></section>`;

  const page=content.querySelector('.safety-grouped-page');
  const articles=[...page.querySelectorAll('.safety-confirm-list article')];
  const updateProgress=()=>{const count=articles.filter(item=>item.dataset.status).length,total=articles.length;page.querySelector('#safetyConfirmedCount').textContent=count;page.querySelector('#safetyProgressBar').style.width=`${count/total*100}%`;page.querySelector('#safetyProgressText').textContent=count===total?'已完成全部措施确认，请确认签字':'请逐项确认安全措施落实情况'};
  const setStatus=(article,status)=>{article.dataset.status=status;article.classList.toggle('confirmed',status==='done');article.classList.toggle('not-applicable',status==='na');article.querySelector('.safety-done').classList.toggle('selected',status==='done');article.querySelector('.safety-na').classList.toggle('selected',status==='na');const extra=article.querySelector('.safety-extra');extra.innerHTML=status==='done'?`<label class="site-photo-field"><span>现场照片</span><input class="site-photo-input" type="file" accept="image/*" multiple hidden><button class="photo-upload-button" type="button">＋ 上传现场照片</button><div class="site-photo-previews"></div><small>支持 JPG、PNG，可上传多张现场照片</small></label>`:`<label class="na-description-field"><span>不涉及说明</span><textarea maxlength="200" placeholder="请输入该措施不涉及本次作业的原因"></textarea><small>0/200</small></label>`;updateProgress()};
  page.addEventListener('click',event=>{const article=event.target.closest('.safety-confirm-list article');if(event.target.closest('.safety-done')&&article)setStatus(article,'done');if(event.target.closest('.safety-na')&&article)setStatus(article,'na');if(event.target.closest('.photo-upload-button'))event.target.closest('.site-photo-field').querySelector('.site-photo-input').click();if(event.target.closest('.safety-group-toggle')){const section=event.target.closest('.safety-risk-group'),list=section.querySelector('.safety-confirm-list');list.hidden=!list.hidden;event.target.textContent=list.hidden?'展开':'收起'}});
  page.addEventListener('input',event=>{if(event.target.matches('.na-description-field textarea'))event.target.nextElementSibling.textContent=`${event.target.value.length}/200`});
  page.addEventListener('change',event=>{if(!event.target.matches('.site-photo-input'))return;const previews=event.target.closest('.site-photo-field').querySelector('.site-photo-previews');previews.innerHTML='';[...event.target.files].forEach(file=>{const reader=new FileReader();reader.onload=()=>previews.insertAdjacentHTML('beforeend',`<figure><img src="${reader.result}" alt="现场照片"><figcaption>${file.name}</figcaption></figure>`);reader.readAsDataURL(file)})});
  page.querySelector('#batchSafetyDone').onclick=()=>articles.forEach(item=>setStatus(item,'done'));
  page.querySelector('#batchSafetyNA').onclick=()=>articles.forEach(item=>setStatus(item,'na'));
  const signature=page.querySelector('#safetySignature');signature.onclick=()=>{signature.dataset.signed='true';signature.classList.add('signed');signature.innerHTML='<b>安全生产鞍钢项目</b><small>签字时间：刚刚</small>'};
  page.querySelector('#backSafetyTodo').onclick=page.querySelector('#cancelSafetyConfirm').onclick=()=>openView('todo');
  page.querySelector('#submitSafetyConfirm').onclick=()=>{const pending=articles.filter(item=>!item.dataset.status);if(pending.length){pending[0].scrollIntoView({behavior:'smooth',block:'center'});return toast(`还有 ${pending.length} 项安全措施未确认`)}if(!signature.dataset.signed)return toast('请由现场安全人员确认签字');updateTodoFlowStage(row,'briefing');todoState='measure';openView('todo');toast('安全措施已提交，进入安全交底')};
  updateProgress();
}

const safetyBriefingDrafts={};
function updateTodoFlowStage(row,stage){
  const id=row&&row[0]; if(!id)return;
  const source=todoRows.measure||[]; const index=source.findIndex(item=>item[0]===id);
  let record=index>=0?source[index]:row;
  if(index>=0)source.splice(index,1);
  if(stage==='briefing'){record[6]='安全交底';source.unshift(record)}
  if(stage==='receive'){record[6]='接收交底';source.unshift(record)}
  if(stage==='accept'){record[6]='验收审批';(todoRows.accept||[]).unshift(record)}
  if(stage==='approval'){record[6]='作业审批';(todoRows.approval||[]).unshift(record)}
}

function renderEnhancedSafetyBriefing(row){
  const job=todoJob(row);
  const steps=[
    ['作业前','检查作业人员资质、安全防护设备、个体防护用品、应急救援装备及作业工器具，确定双方监护人员。','资质或防护用品不符合要求','逐人核验资质和防护用品，应急器材完好有效。'],
    ['作业前','封闭作业区域，在进出口周边设置安全警示标志，对设备、物料和能源介质采取可靠隔离并上锁挂牌。','有毒有害气体窜入、误启动','对连通管线加装盲板，切断能源，落实上锁挂牌。'],
    ['作业前','对有限空间进行清洗、物料清空、气体置换和通风，作业人员在外部上风侧进行气体检测。','中毒、窒息、火灾或爆炸','执行“先通风、再检测、后作业”，检测合格后办理作业票。'],
    ['作业中','作业人员在入口处完成进入登记后进入，合理安排作业时间并采取人员轮换。','人员遗漏、长时间作业导致伤害','严格执行出入登记，设置合理轮换时间。'],
    ['作业中','作业过程中保持持续通风和气体检测，作业单位、属地单位监护人员全程在岗。','气体指标异常、监护缺位','报警或通风中断时立即停止作业并组织撤离。'],
    ['作业后','将全部设备和工具带离有限空间，清点人员和设备，确认无遗留后关闭进出口。','人员或工器具遗留','执行人员、工器具双清点，现场负责人复核。'],
    ['作业后','恢复现场环境，经验收后解除隔离和封闭措施，安全撤离作业现场。','设施误恢复、现场留有隐患','验收人确认现场清理完成后方可恢复设施。']
  ];
  const zones=['有限空间进出口及周边 5 米警戒区域，非作业人员禁止进入。'];
  title.textContent='安全交底';subtitle.textContent='维护作业步骤、主要风险、安全防范措施及危险禁入区域';
  content.innerHTML=`<div class="page-breadcrumb">我的待办　/　安全措施　/　安全交底</div><section class="enhanced-briefing-page panel"><header class="enhanced-briefing-head"><div><button class="ghost" id="backEnhancedBriefing">← 返回安全措施</button><h2>安全交底内容</h2><p><b>${job.id}</b>　${job.name}　<span>${job.level}</span></p></div><div class="briefing-head-actions"><button class="ghost" id="saveBriefingDraft">保存草稿</button><button class="primary" id="addBriefingStep">＋ 新增作业步骤</button></div></header><section class="briefing-edit-section"><div class="briefing-edit-title"><span><i>1</i><b>作业步骤与安全防范措施</b></span><small>内容参照有限空间作业步骤、安全防范措施及审批表</small></div><div class="briefing-step-table"><div class="briefing-step-row header"><b>序号</b><b>作业阶段</b><b>作业步骤</b><b>主要安全风险</b><b>安全防范措施</b><b>操作</b></div><div id="briefingStepRows">${steps.map((item,index)=>briefingStepRow(item,index)).join('')}</div></div></section><section class="briefing-edit-section"><div class="briefing-edit-title"><span><i>2</i><b>周边危险禁入区域告知</b></span><button class="primary small" id="addDangerZone">＋ 新增告知内容</button></div><p class="briefing-zone-tip">请明确告知与作业无关人员禁止进入的范围、设施和特殊要求。</p><div class="danger-zone-list" id="dangerZoneList">${zones.map((zone,index)=>dangerZoneRow(zone,index)).join('')}</div></section><section class="briefing-edit-section"><div class="briefing-edit-title"><span><i>3</i><b>交底确认</b></span></div><label class="briefing-ack"><input type="checkbox" id="briefingAck"> 我已核对作业内容、安全风险、防范措施及作业区域禁入范围。</label><div class="briefing-signature-row"><label>附件 <input id="briefingFiles" type="file" multiple hidden><button class="ghost" id="uploadBriefingFiles" type="button">上传文件</button><small id="briefingFileNames">未选择文件</small></label><label>安全交底人签字 <button class="signature-box" id="enhancedBriefingSignature">✍ 点击签字</button></label></div></section><footer class="enhanced-briefing-footer"><button class="ghost" id="cancelEnhancedBriefing">取消</button><button class="primary" id="submitEnhancedBriefing">提交交底</button></footer></section>`;
  const page=content.querySelector('.enhanced-briefing-page'),stepRows=page.querySelector('#briefingStepRows'),zoneList=page.querySelector('#dangerZoneList');
  const stepSection=page.querySelector('.briefing-edit-section');
  stepSection.insertAdjacentHTML('afterend','<section class="briefing-edit-section safety-measures-independent"><div class="briefing-edit-title"><span><i>2</i><b>安全防范措施</b></span><button class="primary small" id="addIndependentMeasure">＋ 新增措施</button></div><div id="independentMeasureList">'+steps.map(item=>'<div class="independent-measure-row"><textarea placeholder="请输入安全防范措施">'+item[3]+'</textarea><button class="danger-zone-delete">删除</button></div>').join('')+'</div></section>');
  page.querySelector('#addIndependentMeasure').onclick=()=>page.querySelector('#independentMeasureList').insertAdjacentHTML('beforeend','<div class="independent-measure-row"><textarea placeholder="请输入安全防范措施"></textarea><button class="danger-zone-delete">删除</button></div>');
  const renumber=()=>stepRows.querySelectorAll('.briefing-step-row:not(.header)').forEach((row,index)=>row.querySelector('.briefing-row-number').textContent=index+1);
  page.querySelector('#addBriefingStep').onclick=()=>{stepRows.insertAdjacentHTML('beforeend',briefingStepRow(['作业中','','',''],stepRows.children.length));renumber();stepRows.lastElementChild.querySelector('textarea').focus()};
  page.querySelector('#addDangerZone').onclick=()=>{zoneList.insertAdjacentHTML('beforeend',dangerZoneRow('',zoneList.children.length));zoneList.lastElementChild.querySelector('textarea').focus()};
  page.addEventListener('click',event=>{const rowEl=event.target.closest('.briefing-step-row');if(event.target.closest('.briefing-delete-step')){rowEl.remove();renumber()}if(event.target.closest('.briefing-move-up')&&rowEl.previousElementSibling){rowEl.parentElement.insertBefore(rowEl,rowEl.previousElementSibling);renumber()}if(event.target.closest('.briefing-move-down')&&rowEl.nextElementSibling){rowEl.parentElement.insertBefore(rowEl.nextElementSibling,rowEl);renumber()}if(event.target.closest('.danger-zone-delete'))event.target.closest('.danger-zone-row').remove()});
  const signature=page.querySelector('#enhancedBriefingSignature');signature.onclick=()=>{signature.dataset.signed='true';signature.classList.add('signed');signature.innerHTML='<b>安全生产鞍钢项目</b><small>安全交底人 · 刚刚</small>'};
  page.querySelector('#uploadBriefingFiles').onclick=()=>page.querySelector('#briefingFiles').click();page.querySelector('#briefingFiles').onchange=event=>page.querySelector('#briefingFileNames').textContent=[...event.target.files].map(file=>file.name).join('、')||'未选择文件';
  page.querySelector('#saveBriefingDraft').onclick=()=>toast('安全交底草稿已保存');page.querySelector('#backEnhancedBriefing').onclick=()=>renderGroupedSafetyConfirmation(row);page.querySelector('#cancelEnhancedBriefing').onclick=()=>openView('todo');
  page.querySelector('#submitEnhancedBriefing').onclick=()=>{if(!stepRows.children.length)return toast('请至少维护一条作业步骤');if([...stepRows.querySelectorAll('textarea')].some(input=>!input.value.trim()))return toast('请完整填写作业步骤、风险和防范措施');if(!zoneList.children.length||[...zoneList.querySelectorAll('textarea')].some(input=>!input.value.trim()))return toast('请完整填写周边危险禁入区域告知');if(!page.querySelector('#briefingAck').checked)return toast('请确认已核对安全交底内容');if(!signature.dataset.signed)return toast('请安全交底人确认签字');const payload={steps:[...stepRows.children].map(item=>({stage:item.querySelector('select').value,step:item.querySelector('[aria-label="作业步骤"]').value,risk:item.querySelector('[aria-label="主要安全风险"]').value,measure:item.querySelector('[aria-label="安全防范措施"]').value})),zones:[...zoneList.querySelectorAll('textarea')].map(item=>item.value.trim())};safetyBriefingDrafts[row[0]]=payload;updateTodoFlowStage(row,'receive');todoState='measure';openView('todo');toast('安全交底已提交，进入接收交底')};
}

function briefingStepRow(item,index){return `<div class="briefing-step-row"><span class="briefing-row-number">${index+1}</span><select aria-label="作业阶段">${['作业前','作业中','作业后'].map(stage=>`<option ${stage===item[0]?'selected':''}>${stage}</option>`).join('')}</select><textarea aria-label="作业步骤" placeholder="请输入作业步骤">${item[1]}</textarea><textarea aria-label="主要安全风险" placeholder="请输入主要安全风险">${item[2]}</textarea><textarea aria-label="安全防范措施" placeholder="请输入安全防范措施">${item[3]}</textarea><div class="briefing-row-actions"><button class="briefing-move-up" title="上移">↑</button><button class="briefing-move-down" title="下移">↓</button><button class="briefing-delete-step" title="删除">删除</button></div></div>`}
function dangerZoneRow(value,index){return `<div class="danger-zone-row"><i>${index+1}</i><textarea aria-label="危险禁入区域告知" maxlength="300" placeholder="请输入危险禁入区域、范围及告知要求">${value}</textarea><button class="danger-zone-delete">删除</button></div>`}

function renderEnhancedReceiveBriefing(row,payload){
  payload=payload||{steps:[['作业前','请维护作业步骤','请维护主要安全风险','请维护安全防范措施']].map(item=>({stage:item[0],step:item[1],risk:item[2],measure:item[3]})),zones:['有限空间进出口及周边 5 米警戒区域，非作业人员禁止进入。']};
  const job=todoJob(row),sections=[
    ['basic','作业基本信息',`<div class="receive-basic-grid"><p><span>作业票编号</span><b>${job.id}</b></p><p><span>作业内容</span><b>${job.name}</b></p><p><span>作业类型/等级</span><b>${job.type} / ${job.level}</b></p><p><span>作业负责人</span><b>${job.owner}</b></p><p><span>作业区域</span><b>${job.area}</b></p><p><span>计划时间</span><b>${job.time}</b></p></div>`],
    ['steps','作业步骤',`<div class="receive-step-list">${payload.steps.map((item,index)=>`<article><i>${index+1}</i><div><span>${item.stage}</span><b>${item.step}</b></div></article>`).join('')}</div>`],
    ['risks','风险点和风险管控措施',`<div class="receive-risk-table"><div class="header"><b>序号</b><b>风险点</b><b>风险管控措施</b></div>${payload.steps.map((item,index)=>`<div><span>${index+1}</span><strong>${item.risk}</strong><p>${item.measure}</p></div>`).join('')}</div>`],
    ['zones','周边危险禁入区域告知',`<div class="receive-zone-list">${payload.zones.map((item,index)=>`<p><i>${index+1}</i><span>${item}</span></p>`).join('')}</div>`]
  ];
  title.textContent='接收交底';subtitle.textContent='请操作人逐项阅读安全交底内容并确认接收';
  content.innerHTML=`<div class="page-breadcrumb">我的待办　/　安全措施　/　接收交底</div><section class="enhanced-receive-page panel"><header class="enhanced-receive-head"><div><button class="ghost" id="backToBriefing">← 返回安全交底</button><h2>接收安全交底</h2><p><b>${job.id}</b>　${job.name}</p></div><div class="receive-progress"><b id="receiveCount">0</b><span>/ 4 项已阅读确认</span></div></header><div class="receive-life-tip"><b>为了您的生命安全，请认真阅读以下安全交底内容</b><span>内容由安全交底人确认后发布</span></div><div class="receive-content-sections">${sections.map((section,index)=>`<section class="receive-content-card" data-section="${section[0]}"><header><div><i>${index+1}</i><b>${section[1]}</b></div><label><input type="checkbox" class="receive-section-check"> <span>确认已阅读</span></label></header><div class="receive-card-body">${section[2]}</div></section>`).join('')}</div><section class="receive-final-confirm"><div class="receive-person"><span>交底接收人</span><b>王安全</b><small>现场作业操作人</small></div><label>接收人签字 <button class="signature-box" id="receiveSignature">✍ 点击签字</button></label><label class="receive-agreement"><input type="checkbox" id="receiveAgreement"> 本人已知晓作业内容、安全风险、管控措施及作业区域禁入范围，并承诺严格执行。</label></section><footer class="enhanced-receive-footer"><button class="ghost" id="cancelReceiveBriefing">取消</button><button class="primary" id="submitReceiveBriefing">确认接收交底</button></footer></section>`;
  const page=content.querySelector('.enhanced-receive-page'),checks=[...page.querySelectorAll('.receive-section-check')],update=()=>{const count=checks.filter(item=>item.checked).length;page.querySelector('#receiveCount').textContent=count;page.querySelectorAll('.receive-content-card').forEach((card,index)=>card.classList.toggle('read',checks[index].checked))};
  checks.forEach(check=>check.onchange=update);const signature=page.querySelector('#receiveSignature');signature.onclick=()=>{signature.dataset.signed='true';signature.classList.add('signed');signature.innerHTML='<b>王安全</b><small>接收签字 · 刚刚</small>'};
  page.querySelector('#backToBriefing').onclick=()=>renderEnhancedSafetyBriefing(row);page.querySelector('#cancelReceiveBriefing').onclick=()=>openView('todo');page.querySelector('#submitReceiveBriefing').onclick=()=>{if(checks.some(item=>!item.checked))return toast('请逐项阅读并确认全部安全交底内容');if(!page.querySelector('#receiveAgreement').checked)return toast('请确认已知晓并承诺执行安全交底');if(!signature.dataset.signed)return toast('请交底接收人确认签字');updateTodoFlowStage(row,'approval');todoState='approval';openView('todo');toast('安全交底已接收，进入作业审批')};update();
}

const todoStageActionOriginal=handleTodoAction;
const approvalProgress={};
function renderApprovalPage(row){const job=todoJob(row),key=row[0],names=['作业负责人意见','所在单位意见'],done=approvalProgress[key]||0;title.textContent='作业审批';subtitle.textContent='按配置流程逐节点完成审批';content.innerHTML=`<div class="page-breadcrumb">我的待办　/　作业审批</div><section class="workflow-page panel"><header><h2>审批流程</h2><span>作业编号：${job.id}</span></header>${names.map((name,i)=>`<section class="workflow-step ${i<done?'is-done':''}"><h3>${i+1}. ${name} ${i<done?'✓ 已通过':''}</h3>${i===done?'<label>审核意见 <textarea placeholder="请输入审核意见"></textarea></label><label><input type="radio" name="approve" checked> 同意　<input type="radio" name="approve"> 不同意</label><button class="primary approve-one">提交</button>':''}</section>`).join('')}<footer><button class="ghost" id="cancelWorkflow">取消</button></footer></section>`;content.querySelector('#cancelWorkflow').onclick=()=>openView('todo');content.querySelector('.approve-one')?.addEventListener('click',()=>{approvalProgress[key]=done+1;if(approvalProgress[key]>=names.length){updateTodoFlowStage(row,'site');todoState='site';openView('todo');toast('审批完成，进入现场实施')}else renderApprovalPage(row)})}
function renderAcceptancePage(row){const job=todoJob(row);title.textContent='提交验收';subtitle.textContent='维护完工验收信息';content.innerHTML=`<div class="page-breadcrumb">我的待办　/　现场实施　/　提交验收</div><section class="workflow-page panel"><header><h2>提交验收</h2><span>作业编号：${job.id}</span></header><label>实际开始时间<input type="datetime-local" value="2026-09-03T17:30"></label><label>实际完工时间<input type="datetime-local" value="2026-09-03T17:31"></label><label>结束确认标准<textarea>1.现场无遗留的零件、工具等。2.现场整理整顿，器材归位。3.作业人员全部撤出有限空间。</textarea></label><label>作业视频记录 <button class="primary small">上传文件</button></label><label>完工图片 <button class="photo-upload-button">＋ 上传现场照片</button></label><label>作业负责人签字 <button class="signature-box" id="acceptSign">点击签字</button></label><footer><button class="ghost" id="cancelAcceptance">取消</button><button class="primary" id="submitAcceptance">提交</button></footer></section>`;content.querySelector('#cancelAcceptance').onclick=()=>openView('todo');content.querySelector('#acceptSign').onclick=e=>{e.currentTarget.dataset.signed='true';e.currentTarget.textContent='安全生产鞍钢项目 · 已签字'};content.querySelector('#submitAcceptance').onclick=()=>{if(!content.querySelector('#acceptSign').dataset.signed)return toast('请作业负责人签字');updateTodoFlowStage(row,'accept');todoState='accept';openView('todo');toast('验收信息已提交，进入验收审批')}}
function renderAcceptanceReviewPage(row){const job=todoJob(row);title.textContent='验收审批';subtitle.textContent='审核完工验收信息';content.innerHTML=`<div class="page-breadcrumb">我的待办　/　验收审批</div><section class="workflow-page panel"><header><h2>验收流程</h2><span>作业编号：${job.id}</span></header><p>实际开始时间：2026-09-03 17:30</p><p>实际完工时间：2026-09-03 17:31</p><label>验收审批意见<textarea placeholder="请输入验收审批意见"></textarea></label><label><input type="radio" checked> 同意　<input type="radio"> 不同意</label><label>审核人签字 <button class="signature-box" id="reviewSign">点击签字</button></label><footer><button class="ghost" id="cancelReview">取消</button><button class="primary" id="submitReview">提交</button></footer></section>`;content.querySelector('#cancelReview').onclick=()=>openView('todo');content.querySelector('#reviewSign').onclick=e=>{e.currentTarget.dataset.signed='true';e.currentTarget.textContent='王安全 · 已签字'};content.querySelector('#submitReview').onclick=()=>{if(!content.querySelector('#reviewSign').dataset.signed)return toast('请审核人签字');const i=(todoRows.accept||[]).findIndex(x=>x[0]===row[0]);if(i>=0)todoRows.accept.splice(i,1);todoState='accept';openView('todo');toast('验收审批完成，作业票已结束')}}
handleTodoAction=function(action,row){if(action==='安全交底')return renderEnhancedSafetyBriefing(row);if(action==='接收交底')return renderEnhancedReceiveBriefing(row,safetyBriefingDrafts[row&&row[0]]);if(action==='作业审批')return renderApprovalPage(row);if(action==='提交验收')return renderAcceptancePage(row);if(action==='验收审批')return renderAcceptanceReviewPage(row);return todoStageActionOriginal(action,row)};
const riskDynamicOriginal=handleTodoAction;handleTodoAction=function(action,row){if(action!=='风险评估')return riskDynamicOriginal(action,row);riskDynamicOriginal(action,row);const page=document.querySelector('.risk-assessment-page');if(!page)return;const templates={触电:['作业区域已隔离并设置警示标识','作业人员防护用品及资质已核验'],火灾:['现场监护人员全程在岗','消防器材配置到位'],高处坠落:['高处作业人员正确佩戴安全带','作业平台及防护栏杆验收合格'],物体打击:['作业区域设置硬隔离和警示标识','工器具采取防坠措施']};const renderMeasures=()=>{const selected=[...page.querySelectorAll('.risk-page-point.selected b')].map(x=>x.textContent);const box=page.querySelector('.risk-page-measures');box.innerHTML=(selected.length?selected:['触电']).flatMap(r=>(templates[r]||['请补充该风险的管控措施']).map(m=>`<p><b>${r}</b><span>${m}</span><button class="measure-delete">删除</button></p>`)).join('')};page.querySelectorAll('.risk-page-point').forEach(el=>{el.onclick=()=>{el.classList.toggle('selected');el.querySelector('input').checked=el.classList.contains('selected');renderMeasures()}});page.querySelector('#toggleMeasures')?.addEventListener('click',e=>{const box=page.querySelector('.risk-page-measures');box.hidden=!box.hidden;e.currentTarget.textContent=box.hidden?'展开':'收起'});page.querySelector('#addPageMeasure')?.addEventListener('click',()=>{page.querySelector('.risk-page-measures').insertAdjacentHTML('beforeend','<p><b>自定义风险</b><input placeholder="请输入安全防范措施"><button class="measure-delete">删除</button></p>')});renderMeasures()};
